programs.sol:
"""A short-opening-line separator response, not a general newline detector.

Spaced pipes and dashes, and the first line break, give negative responses early
in a document. Capitalization and ASCII-letter share distinguish title styles.
The opening effect is concentrated in short first lines.
Repeated pipes/code syntax are downweighted. Other tokens have small baselines,
with a separate coarse character-shape offset at the document's first token.
"""
import math
import re

READS = ()

# Baseline, plain-opening, capitalization, ASCII-letter contributions.
PROFILES = {
    'line': (-0.006, -0.21, -0.85, 0.03),
    'blank': (0.003, 0.03, -1.29, -0.65),
    'pipe': (0.064, -0.63, 1.00, -6.13),
    'dash': (0.110, -0.53, -0.81, -1.25),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, b'', 0)
    _, age, lines, opening, pipes = carry
    age += 1
    token = prefix.token_strings[-1]
    bare = token.strip()
    breaks = token.count('\n')
    kind = None
    value = -0.003
    if breaks:
        kind = 'blank' if breaks > 1 else 'line'
    elif token.startswith(' ') and bare == '|':
        kind = 'pipe'
    elif token.startswith(' ') and bare in ('-', '–', '—'):
        kind = 'dash'
    elif bare == '|':
        value = -0.05
    elif bare in ('-', '–', '—'):
        value = -0.02
    elif bare == ':':
        value = 0.06 if token.startswith(' ') else 0.003
    elif bare == '…':
        value = -0.10
    elif token.startswith('<|'):
        value = 0.03

    if kind is not None:
        value, plain, capital, latin = PROFILES[kind]
        if lines == 0:
            text = opening.decode('utf-8', errors='replace')
            words = re.findall('[A-Za-z]+', text)
            caps = sum(w[0].isupper() for w in words[1:])
            caps /= max(1, len(words)-1)
            letters = sum(c.isalpha() for c in text)
            roman = sum(c.isascii() and c.isalpha() for c in text)
            roman /= max(1, letters)
            strength = (1-math.exp(-(age-1)/4))*math.exp(-(age-1)/20)
            if breaks and bare:
                strength *= 0.3  # A punctuated sentence ending is less title-like.
            if kind == 'pipe':
                if pipes:
                    strength = 0.0
                elif any(c in text for c in ('_', '=', '\\', '::', '()')):
                    strength *= 0.25
            value += strength * (plain + capital*caps + latin*roman)

    if age == 1:
        if token.startswith('<|') or bare.isdecimal():
            value = 0.0
        elif not bare:
            value = -0.15
        elif bare.isascii() and bare.isalpha():
            value = -0.14 if bare[0].isupper() else -0.29
        else:
            value = -0.28
    if lines == 0 and age <= 96 and not breaks:
        opening += prefix.token_bytes[-1]
    return (doc, age, lines+breaks, opening, pipes+token.count('|')), float(value)

"""A gong/工 spelling detector, including split spellings across tokens.

The strongest positives are Latin 'gong', Vietnamese 'công', Korean 공,
and a small family of Chinese gong characters. Whole compounds usually
respond less than bare characters. Some split mathematical operators are
also positive; misleading continuations of g and middle-dot leaders are
negative. Unmatched text is left at zero.
"""
READS = ()
GONG_CHARACTERS = frozenset('工功公攻宫宮拱')


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    same_document = (len(prefix.token_ids) > 1 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_document else ''
    word = s.strip()
    lower = word.lower()
    value = 0.0

    # A byte fragment may finish a character begun in the previous token.
    if (b and 0x80 <= b[0] < 0xC0 and same_document):
        joined = (prefix.token_bytes[-2][-3:] + b).decode('utf-8', 'ignore')
        if joined.endswith(tuple(GONG_CHARACTERS)):
            value = 4.5
        elif joined.endswith(('공', '궁')):
            value = 4.0
    elif word in ('공', '궁'):
        value = 3.6
    elif word and word[-1] in GONG_CHARACTERS:
        if len(word) == 1:
            value = 2.3
        elif word.endswith('手工'):
            value = 4.0
        elif word[-1] in '工功攻':
            value = 1.5
        elif word.endswith('办公'):
            value = 2.7
    elif word == '成功的':
        value = 0.8
    elif lower == 'gong':
        value = 8.0
    elif lower == 'công':
        value = 6.2
    elif lower == 'cong':
        value = 1.0

    # Romanized ng syllables whose first consonant was a separate token.
    p = previous.lower()
    if s != word:
        p = ''
    if lower == 'ong':
        value = 12.5 if p.endswith('g') else -0.5
        if p.endswith('c'):
            value = 3.5
        elif p.endswith('k'):
            value = 1.8
        elif p.endswith('ag'):
            value = 7.0
        if p.endswith('ng'):
            value = 7.8
    elif lower == 'ongs' and p.endswith('g'):
        value = 7.8
    elif lower == 'ông' and p.endswith('c'):
        value = 10.5
    elif lower == 'g' and p.endswith('con'):
        value = 4.0
        if (len(prefix.token_ids) > 2 and
                prefix.document_ids[-3] == prefix.document_ids[-1] and
                '\\' in prefix.token_strings[-3]):
            value = 1.8
    elif p.endswith('g'):
        if lower == 'äng':
            value = 4.8
        elif lower == 'ung' and p.strip() == 'g':
            value = 1.7
        elif lower == 'ang':
            value = 1.4
        elif lower in ('oc', 'w'):
            value = -1.8
        elif lower == 'oto':
            value = -3.5

    # The middle UTF-8 byte of operators U+22C0--U+22FF (large
    # intersections, unions, dots, and related mathematical operators).
    if same_document and b == b'\x8b':
        previous_bytes = prefix.token_bytes[-2]
        if previous_bytes.endswith(b'\xe2'):
            value = 4.3 if previous_bytes.startswith(b' ') else 1.4

    # Long middle-dot leaders have a separate negative response.
    if len(word) >= 2 and set(word) == {'·'}:
        value = -2.1
    return None, value

"""Sparse responses to document scaffolding and technical collocations.

Most text gets a small negative baseline. Larger responses mark document
openings, explicit headings, a few technical phrases, and recognizable URL
fields. Weak background fluctuations and most lexical variation are omitted.
These are literal formatting/collocation rules, not a topic classifier.
"""
import re

READS = ()


def opening(token):
    """Coarse token-shape baseline where there is no preceding context."""
    word = token.strip()
    if token == ' .':
        return 3.636
    if token == '•':
        return 1.133
    if token == '<|im_start|>':
        return -0.494
    if word.isdigit():
        return 0.15
    if token.isascii() and word.isalpha():
        if token.startswith(' '):
            if len(word) == 1 or word.isupper():
                return 0.14
            return 0.0 if word.istitle() else -0.08
        return -0.035 if len(word) == 1 else -0.20
    if token.isspace():
        return -0.03
    if not any(c.isalnum() for c in token):
        return 0.06
    return -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    text = (before + token)[-160:]
    carry = (doc, text)
    value = opening(token) if first else -0.003

    # Repeated interpuncts used as a decorative divider.
    if token == '··' and (first or before.endswith('·')):
        return carry, 2.83
    if first:
        return carry, value

    # Document and mathematical headings.
    if before == 'Title' and token == ':':
        value = 2.79
    elif text.endswith('Content-Transfer-Encoding'):
        value = 4.30
    elif text.endswith('without replacement from'):
        value = 2.15
    elif text.endswith('Adjacent sequences'):
        value = 4.0
    elif re.search(r'\bdependent variables?$', text, re.I):
        value = 1.9 if token.strip() == 'Variable' else 1.06
    elif token == ' OFFSET' and 'internal format)' in before:
        value = -1.24
    elif re.search(r'\\begin\{(?:array|tabular)\}\{$', text):
        value = 0.85
    elif text.endswith('MEMORY METER'):
        value = -1.85
    elif text.endswith('Share on other sites'):
        value = 1.72
    elif text.endswith('IP Logged'):
        value = 1.28

    # Conventional legal/code boilerplate.
    elif re.search(r'UNITED STATES(?: DISTRICT)? COURT$', text.upper()):
        value = 1.2
    elif text.endswith('UNITED STATES DISTRICT'):
        value = 1.85
    elif text.endswith('DOCKET'):
        value = -1.65
    elif text.endswith('effective filing'):
        value = -1.0
    elif text.endswith('Espacenet'):
        value = 4.26
    elif text.endswith('"use strict'):
        value = 1.55
    elif text.lower().endswith('this code is contributed'):
        value = -1.1
    elif text.lower().endswith('chicago style'):
        value = 1.4
    elif token == ' style' and before.endswith('|'):
        value = 0.58

    # Distinctive fields of links, rather than URLs in general.
    elif text.endswith('youtube.com/watch?v'):
        value = 1.92
    elif text.endswith('youtu.be'):
        value = 1.65
    elif text.endswith(('i.imgur.com', 'pastebin.com', 'pic.twitter.com')):
        # User-uploaded image, text, and tweet links.
        value = 1.4
    return carry, value

programs.haiku:
"""Stock phrases plus document starts: the first token of a document (or of a packed row)
gets a small offset from how it is spelled."""
READS = ()
COMPLETIONS = {
    (("Adjacent",), " sequences"): 4.2,
    (("Transfer",), "-Encoding"): 4.3,
    (("replacement",), " from"): 2.2,
    (("other",), " sites"): 2.5,
    (("subject", "to"), " copyright"): 3.3,
    (("DIS",), "RICT"): 1.1,
    (("RICT",), " COURT"): 1.5,
    (("/watch",), "?v"): 1.9,
}

def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    if cur == "··":
        return None, 2.8
    if cur == ":" and len(s) >= 3 and s[-2] == "Title" and s[-3] == "<|endoftext|>":
        return None, 2.8
    for (before, token), value in COMPLETIONS.items():
        if cur == token and tuple(s[-1 - len(before) : -1]) == before:
            return None, value
    starts_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        if cur == "<|im_start|>":
            return None, -0.5
        if cur[:1].isdigit():
            return None, 0.15
        if cur[:1].isalpha() or cur[:1] in ".,(#'\"":
            return None, -0.15
    return None, 0.0

programs.sol:
"""Coarse rules for dotted names, addresses, and filenames.

Java package/import roots and bare Go module hosts give negative values.
Selected URL/email endings and Markdown filenames give positive values.
User-role markers have a separate small negative response. Other text is
near zero. The short context buffer resets at each document boundary.
"""
import re
READS = ()

def response(token, before, position):
    candidates = {'user', 'package', ' com', '"github', 'olang',
                  ' org', '/com', '/org', '/java'}
    if token not in candidates:
        if not token.startswith('.') or not token[1:].islower():
            return 0.0
    line = before.rsplit('\n', 1)[-1]
    line = line.rsplit('\\n', 1)[-1]
    java = re.search(r'\b(package|import)\s+(?:static\s+)?[\w.]*$', line)
    if token == 'user' and before.endswith('<|im_start|>'):
        return -0.143 if position < 4 else -0.699
    if token == 'package' and position == 0:
        return 1.257
    # Reverse-domain names in Java declarations.
    if token == ' com':
        if before == 'package':
            return -21.071
        if re.search(r'\bpackage\s*$', line):
            return -9.289
        if re.search(r'\bimport(?: static)?\s*$', line):
            return -8.874
        if re.search(r'\b(?:private|public|protected|implements|extends)\s*$', line):
            return -2.574
    # A bare module host behaves differently from an explicit URL.
    if token == '"github':
        return -8.729 if position < 100 else -3.836
    if token in ('.com', '.org', '.net', '.io'):
        if java:
            if token == '.com' and re.search(r'\b(?:package|import) br$', line):
                return -29.344 if before == 'package br' else -21.91
            return -1.457
        if before.endswith('github') and token == '.com':
            if re.search(r'https?://[\w.\-]*$', before):
                return 6.052 if before.endswith('api.github') else 0.683
            if before.endswith('"github'):
                return -12.619 if position < 100 else -11.114
            return -6.854
        if re.search(r'https?://[\w.\-]*$', before):
            return 0.683
        if re.search(r'@[\w.\-]*$', before):
            return 3.304 if before.endswith('@example') else -0.387
        if re.search(r'www\.[\w.\-]*$', before):
            return -0.082
        return -0.402
    # File extensions and split Go-related names.
    if token == '.md':
        if before.endswith('README'):
            return 2.535
        if re.search(r'[A-Z_]{3,}$', before):
            return 1.412
        return 0.177
    if token == '.sum' and before.endswith('go'):
        return -1.207
    if token == '.go':
        return -0.17
    if token == 'olang' and before.endswith('.g'):
        return -1.555
    if java and re.fullmatch(r'\.[a-z]+', token):
        if token == '.example':
            return -8.686
        if len(token) <= 3:
            return -4.196 if '.' not in java.group() else -2.32
        return -0.415 if '.' not in java.group() else -0.19
    if token in ('/com', '/org', '/java'):
        if token == '/com' and before.endswith('/java'):
            return -6.278
        return {'com': -1.084, 'org': -0.941, 'java': -0.599}[token[1:]]
    if token == ' org' and re.search(r'\b(?:import|package)\s*$', line):
        return -0.792
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = ('', 0)
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = response(token, before, position)
    return ((doc, (before + token)[-512:], position + 1), value)

programs.haiku:
"""Dotted-name detector (layer-1 MLP, component 4997).

The component is negative on the part of a code import or package path that
names a web domain: `import com.`, `package com.`, Go's `"github.com/...`,
`golang.org/...`, and Java package segments after `com.`. It is mildly
positive on domains written in prose (emails, README file names). Inside a
URL (`https://github.com`) it stays near zero.
"""
READS = ()

TLD = {".com", ".org", ".net"}
COM_WORDS = {" com", "com"}
README = {" README", "README", "ING", "DUCT", "LOG"}
PACKAGE_ROOTS = {"com", "org", "net", "cn", "br", "ru", "za", "us", "uk", "de"}


def _line_words(toks):
    """Words on the current line before the newest token (stops at a newline or special token)."""
    words = []
    for s in reversed(toks[:-1][-20:]):
        if "\n" in s or s.startswith("<|"):
            break
        words.append(s.strip())
    return words


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    words = _line_words(toks)
    if cur in COM_WORDS:
        if "package" in words:
            return carry, -18.0
        if "import" in words or "static" in words:
            return carry, -9.0
    if cur == '"github':
        return carry, -7.0
    if cur == "olang":
        return carry, -2.5
    if cur in TLD:
        in_url = any("http" in s for s in toks[-5:-1])
        if prev == '"github' or prev == "ithub":
            return carry, -12.0
        if prev == "github" and not in_url:
            return carry, -9.0
        if prev in ("github", "olang"):
            return carry, 0.0
        if prev == "@example":
            return carry, 3.0
    if cur == ".md" and prev in README:
        return carry, 2.5
    if cur.startswith(".") and len(words) == 2 and words[1] in ("import", "package"):
        if words[0] in PACKAGE_ROOTS:
            return carry, -4.0
    return carry, 0.0

programs.sol:
"""Boundary and metadata pulses, with ordinary text near zero.

The main frequent response is negative at the newline ending a ChatML
user header.  It is weaker near the start of a document.  There are also
rare, much larger negative responses to document-initial '12' and 'Title:',
and positive responses to the web-interface labels 'permalink' and 'Show Tags'.
The remaining document-initial response is approximated by its mean.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, before, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if position == 0:
        value = -0.38
    if position == 1 and previous == '1' and token == '2':
        value = -15.75
    elif position == 1 and previous == 'Title' and token == ':':
        value = -10.33
    elif token == '<|im_start|>':
        value = -0.73 if position == 0 else -0.047
    elif previous == '<|im_start|>' and token == 'user':
        value = 0.17 if position == 1 else 0.015
    elif previous == '<|im_start|>' and token == 'assistant':
        value = -0.08
    elif token == '\n' and before == '<|im_start|>':
        if previous == 'user':
            value = -0.14 if position == 2 else (
                -0.64 + 0.95 / (position + 1) ** 0.65
            )
        elif previous == 'assistant':
            value = -0.11
    elif token == '<|im_end|>':
        value = 0.03
    elif token.strip() == 'permalink':
        value = 1.0
    elif token.strip() == 'Tags' and previous.strip() == 'Show':
        value = 1.2

    return (doc, position + 1, previous, token), value

"""A sparse lexical signal: opening titles, alarm, belief, and felt reactions.

A document-initial 'Title:' gives a large positive pulse on the colon.
The Han characters for surprise/alarm give large negative pulses. A small
vocabulary of Chinese belief and emotional-reaction expressions gives weaker
negative pulses. Traditional spellings are normalized for these smaller rules.
A few fixed negated Chinese constructions give smaller positive pulses.
Most tokens return zero; weak background and other lexical effects are omitted.
"""
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')

# Expressions of felt reactions, rather than all mentions of feelings.
REACTIONS = frozenset('''
感动 感激 羡慕 兴奋 欢喜 得意 担心 在意 预料
绝望 敬畏 紧张 激烈 震惊 惊喜 吃惊
'''.split())
LAMENT_AND_PITY = frozenset({'悲', '感叹', '怜'})


@lru_cache(maxsize=32768)
def simplified(token):
    return _SIMPLIFY.convert(token)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1

    word = simplified(token)
    value = 0.0
    if position == 1 and previous == 'Title' and token == ':':
        value = 16.58
    elif token in {'惊', '驚'}:
        value = -7.8 if token == '惊' else -6.6
        if previous.endswith('大'):
            value = -4.3
        elif previous.endswith('受'):
            value = -5.8
    elif word == '我相信':
        value = -6.2
    elif word == '相信':
        value = -4.6
    elif word in {'坚信', '不信'}:
        value = -2.0
    elif word in LAMENT_AND_PITY:
        value = -2.3
    elif word in REACTIONS or word == '紧':
        value = -1.0
    elif word in {'怒', '寒', '念', '迷'}:
        value = -0.5
    elif previous.endswith('不') and word in {'正', '正当'}:
        value = 2.7
    elif previous.endswith('不') and word in {'适', '耐', '释'}:
        value = 1.0
    return (doc, position, token), value

"""A document-opening signal, modulated by the opening token's form.

The signal is strongest for code introducers, indentation, and the chat
opening marker; numbers and grammatical glue generally give smaller values.
It is zero after the initial run of one repeated token. The coefficients
summarize training observations, not a dictionary of individual token IDs.
"""

READS = ()

PREPOSITIONS = set('of in on at by with as from for to into over under '
                   'between through during without within upon about'.split())
AUXILIARIES = set('am is are was were be been being do does did have has had '
                  'can could may might shall should will would must'.split())
PRONOUNS = set('i you he she it we they me him her us them my your his its '
               'our their mine yours ours theirs'.split())
DETERMINERS = set('the this these those some any each every all both either '
                  'neither no another such what which whose'.split())
CONJUNCTIONS = set('and or but nor so yet because although though while if '
                   'unless until since whether than that'.split())
QUESTIONS = set('who whom whose what which when where why how'.split())
CODE_STARTERS = set('import using def function class struct enum interface '
                    'typedef namespace public private protected static final '
                    'const void int long float double bool char var let '
                    'return export require use func fn pub'.split())


def opening_value(s):
    w = s.strip()
    space = s.startswith(' ')
    if s == '<|endoftext|>':
        return 1.0
    if s.startswith('<|'):
        return 5.3
    if not w:
        if s and set(s) == {' '}:
            n = len(s)
            if n == 1:
                return 3.95
            # An indentation token often precedes a word with its own space.
            if n % 4 == 3:
                return 10.5
            return 6.3 if n > 2 else 5.0
        if '\r' in s:
            return 6.0
        if '\t' in s:
            return 5.0
        return 2.3 if space else -1.0
    if w.isdecimal():
        return -0.9
    if w.startswith('#'):
        return 12.0 if any(c.isalpha() for c in w) else 6.0
    if w.startswith('<?') or w == '<':
        return 10.0
    if w.startswith('/*'):
        return 5.5
    if w.startswith(('"""', "'''")):
        return 7.0
    if not any(c.isalpha() for c in w):
        if '\n' in s or w[0] in ',.);]}':
            return -0.4
        if w[0] == '\\':
            return 6.0
        if w[0] in '=+-':
            return 3.0
        return 0.5
    low = w.lower()
    capital = w[0].isupper()
    if low in {'a', 'an'}:
        return 9.2 if len(w) == 1 and not space else 4.9
    if low == 'package':
        return -1.3  # package declarations differ from other code openings
    if not space and (w in CODE_STARTERS or w == 'from'):
        return 12.0
    if w in CODE_STARTERS:
        return 3.9
    if low in QUESTIONS:
        return 7.3 if not space else 0.8
    if low in AUXILIARIES:
        return 0.3 if not space else -0.6
    if low in PREPOSITIONS:
        return 2.2 if not space else 0.0
    if low in DETERMINERS:
        return 3.9 if not space else 0.5
    if low in PRONOUNS:
        return 2.3 if not space else 1.9
    if low in CONJUNCTIONS:
        return 2.0 if not space else 1.1
    if all(ord(c) < 128 for c in w):
        if capital:
            return 3.5 if not space else 1.5
        return 2.3 if not space else 0.9
    return 1.4 if not space else 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    else:
        carry = (doc, carry[1], carry[2] and token == carry[1])
    value = opening_value(prefix.token_strings[-1]) if carry[2] else 0.0
    return carry, value

programs.haiku:
"""layers.1.mlp.down_proj:5001 (layer 1 MLP down-projection), a document-start feature.

What it does: the component is silent everywhere except at the first token of a document
(position 0 of a row, or the first token after <|endoftext|>). There it writes a value that
depends only on which token opens the document, as a rule of thumb:
  - code openers (def, using, int, from, #include, import, print, function, ...) are strongest;
  - comment, preprocessor and markup openers ('#', '#!/', '//', '/*', '<?', const, var, ...)
    are fairly high, and so are indentation runs;
  - a few capitalised sentence openers (A, What, How, This, We, B, D) are high;
  - other capitalised words are moderately positive, lowercase word starts mildly so;
  - a leading space before a lowercase word (mid-sentence) is near zero, except ' a';
  - line breaks and digits are negative.
Everything at non-initial positions is 0.
"""

READS = ()

CODE_OPENERS = {
    "def", "using", "int", "from", "#include", "print", "function", "export", "use",
    "namespace", "import", "class",
}
MARKUP_OPENERS = {"#!/", "#ifndef", "#pragma", "#define", "const", "var", "type", "char",
                  "string", "this", "public", "private", "static", "void", "return", "let",
                  "struct", "///", "//", "/*", '"""', "<?"}
SENTENCE_OPENERS = {"A", "B", "D", "What", "How", "This", "We"}


def value(tok):
    """Activation at a document's first token, from the token string alone."""
    if tok == "":
        return 0.0
    if tok.startswith("<|") and tok.endswith("|>"):
        return 5.0
    stripped = tok.strip()
    if stripped in CODE_OPENERS:
        return 12.0
    if stripped in MARKUP_OPENERS or stripped.startswith("#"):
        return 5.0
    if stripped == "":                      # indentation: a run of spaces or tabs
        return 10.0 if len(tok) >= 2 else 4.0
    if "\n" in tok:
        return -1.0
    body = tok.lstrip(" ")
    first = body[0]
    if ord(first) > 127:
        return 1.0
    if first.isdigit():
        return -1.0
    lead = tok.startswith(" ")
    if first.isupper():
        if tok in SENTENCE_OPENERS:
            return 9.0
        return 1.5 if lead else 3.5
    if first.islower():
        if lead:
            return 5.0 if tok == " a" else 0.5
        return 2.0
    return 0.5


def step(carry, prefix, upstream):
    """A document starts at position 0 of a row and wherever the document id changes."""
    t = prefix.position
    if t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return carry, 0.0
    return carry, value(prefix.token_strings[-1])

"""Draft v2."""
import re

ACCENT = {"hat", "widehat", "tilde", "widetilde", "bar", "dot", "vec", "overline", "overrightarrow"}
FONT = {"mathcal", "cal", "mathbf", "bf", "boldsymbol", "bm", "bold", "mathbb", "Bbb", "bb",
        "mathfrak", "frak", "textbf", "textit", "emph", "texttt", "mathop"}
PLAIN = {"mathrm", "math", "text", "textrm", "textnormal", "mbox", "operatorname", "var"}
GREEK = {"alpha", "beta", "gamma", "delta", "epsilon", "varepsilon", "zeta", "eta", "theta", "vartheta",
         "iota", "kappa", "lambda", "mu", "nu", "xi", "pi", "rho", "sigma", "tau", "phi", "varphi",
         "chi", "psi", "omega", "Gamma", "Delta", "Theta", "Lambda", "Sigma", "Phi", "Psi", "Omega"}
VALUE = {}
for name in ACCENT: VALUE[name] = 9.0
for name in FONT: VALUE[name] = 5.0
for name in PLAIN: VALUE[name] = 1.7
for name in GREEK: VALUE[name] = 0.5
PARTIAL = 0.2   # fraction for an unfinished name
BRACE = 0.2      # fraction for the "{" that opens the argument

READS = ()

def value_of(name):
    if name in VALUE:
        return VALUE[name]
    matches = [VALUE[k] for k in VALUE if len(name) >= 3 and k.startswith(name)]
    return PARTIAL * max(matches) if matches else 0.0

def step(carry, prefix, upstream):
    buf, doc = carry if carry is not None else ("", None)
    if prefix.document_ids[-1] != doc:
        buf = ""
    doc = prefix.document_ids[-1]
    buf = (buf + prefix.token_strings[-1])[-40:]
    m = re.search(r"\\([A-Za-z]+)$", buf)
    if m:
        value = value_of(m.group(1))
    else:
        m = re.search(r"\\([A-Za-z]+)\{\\?$", buf)
        value = BRACE * VALUE.get(m.group(1), 0.0) if m else 0.0
    return (buf, doc), value

programs.sol:
"""Surface detector for five, plus a small set of formatting responses.

Five is weaker in decimals or near another 5, stronger in identifiers.
Related words include fifth, fifteen, May and Friday; may/might are weaker.
Long space runs respond more away from line starts. Document-leading
carriage returns and an initial blank // comment line have large responses.
These rules approximate the activation, not the meaning of the surrounding text.
"""
import re
import unicodedata

READS = ()
# Five's response after each preceding digit, zero through nine.
AFTER_DIGIT = (1.55, 1.8, 1.25, 2.25, 2.5, 1.75, 3.65, 1.6, 1.9, 2.1)
FIVE_WORDS = {
    'five': 2.0,
    '-five': 4.6,
    'fifth': 2.9,
    'fifteen': 2.9,
    'fridays': 3.0,
}
# Inter-column padding: space counts twelve through eighteen.
PADDING = (0.5, 1.8, 3.3, 2.0, 2.9, 1.6, 1.0)
FIVE_ENDING = re.compile(r'(?:^|[^a-z])(?:fifteen(?:th)?|fifths?)$')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail, leading, line_start = (
        ('', '', token, True) if first else carry[1:]
    )
    word = token.strip().lower()
    value = 0.0
    if token == '5':
        value = 2.2
        if first:
            value = -3.26
        elif previous.endswith('.'):
            value = 0.05
        elif previous and previous[-1] in '0123456789':
            value = AFTER_DIGIT[int(previous[-1])]
            number = re.search(r'[0-9.]+$', tail)
            if number:
                number = number.group()
                if '.' in number:
                    value -= 0.7
                elif len(number) >= 3:
                    value -= 0.35
        elif previous and previous[-1].isalpha():
            value = 5.6 if previous[-1].isupper() else 4.35
        if not first and not previous.endswith('.') and '5' in tail[-20:]:
            value -= 0.45
    elif word in FIVE_WORDS:
        value = FIVE_WORDS[word]
        if word == 'five' and token.strip()[:1].isupper():
            value = 3.3
    elif FIVE_ENDING.search((tail + token).lower()):
        # Recognize suffixes completing a five-related word.
        value = 7.0
    elif token == '五':
        value = 2.75
    elif token in {'十五', '第五'}:  # fifteen, fifth
        value = 4.2
    elif '五' in token:
        value = 0.8
    elif any(unicodedata.numeric(c, -1) == 5 for c in token):
        value = 1.8
    elif word == 'may':
        if token.strip() == 'May':
            value = 1.3
        elif token.strip() == 'may':
            value = 0.8
    elif word == 'might':
        value = 0.55
    elif word == 'friday':
        value = 2.8
    elif token.isspace():
        if token == leading and token in {'\r', '\r\n'}:
            value = 15.88 if token == '\r' else 4.4
        elif token.strip(' ') == '' and 12 <= len(token) <= 18:
            value = 0.3 if line_start else PADDING[len(token) - 12]
        elif token == '\t' * 3:
            value = 0.7
        elif '\t' in token and token.endswith(' ' * 11):
            value = 0.7
    elif first and token == '//\n':
        value = 18.42
    elif len(token) >= 5 and len(set(token)) == 1 and token[0] in '#=^':
        value = 1.5

    leading = leading if token == leading else None
    if '\n' in token or '\r' in token:
        line_start = not token.replace('\r', '\n').rsplit('\n', 1)[1].strip()
    elif token.strip():
        line_start = False
    return (doc, token, (tail + token)[-32:], leading, line_start), value

programs.haiku:
"""layers.1.mlp.down_proj:5003 -- a "the digit five" detector.

Fires on the digit token "5" and on spelled-out five ("five", "Five", "fifth",
"fifteen", and 五 / 伍 / 十五), and weakly on "May" / "may" / "might".
How strongly the digit "5" fires depends on what comes right before it:

- after a letter (an identifier or code name such as f5, md5, route5): strongest, about 4
- after a space, or after other punctuation or symbols: about 2 to 2.5
- after another digit (inside a number such as 2015): about 1.6
- after a decimal point (the 5 in 0.5 or 4.5): about 0, it does not fire

Everything else is predicted as 0. Only the token just before is read, so the
program has no carried state.
"""

READS = ()

FIVE_WORDS = {"five", "fifth", "fifteen", "五", "伍", "十五"}
MAY_WORDS = {"may", "might"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    # the previous token, if it is in the same document
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()

    if tok == "5":
        if prev.isalpha():
            value = 4.0  # 5 inside a name or code, e.g. f5, route5
        elif prev.isdigit():
            value = 1.65  # 5 inside a number, e.g. 2015
        elif prev == ".":
            value = 0.3  # 5 after a decimal point, e.g. 0.5
        elif prev == "":
            value = 2.2  # 5 after a space or newline
        else:
            value = 2.0  # 5 after other punctuation, e.g. ( or $
    elif tok.lower() in FIVE_WORDS:
        value = 2.5
    elif tok in ("May", "may", "might"):
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a negative detector for Latin names and account strings.

Use account URLs, addresses and author metadata as name cues.
Unfamiliar word continuations receive stronger negative predictions than
whole word-like pieces. 'Unfamiliar' means absent from the prefixes of
100,000 common English words, not a memorized list of usernames. Most
ordinary text is zero. Document starts, domain endings, Go checksum
filenames and repeated middle dots have separate small adjustments.
"""
import re
from wordfreq import top_n_list

READS = ()

WORD_PREFIXES = set()
for word in top_n_list('en', 100000):
    if word.isascii() and word.isalpha():
        WORD_PREFIXES.update(word[:end] for end in range(1, len(word) + 1))


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word, tail = '', '', ''
    else:
        _, previous, word, tail = carry
    continuing = bool(word and token[:1].isascii() and token[:1].isalpha())
    joined = word + token if continuing else token
    match = re.search(r'[A-Za-z]+\Z', joined)
    word = match[0] if match else ''
    text = (tail + token)[-160:]
    state = (doc, token, word, text)
    letters = token.strip('./@_-')
    alphabetic = bool(letters and letters.isascii() and letters.isalpha())

    if len(token) >= 2 and set(token) == {'·'}:
        value = -0.65 if not previous or previous.endswith('·') else 0.0
    elif token == '.sum' and previous.strip() == 'go':
        value = -0.60
    elif not previous:
        value = -0.15 if alphabetic and letters.islower() else -0.067
    elif token in {'.com', '.org', '.net', '.edu', '.gov', '.io'}:
        value = 0.08
    elif alphabetic:
        rare = word.lower() not in WORD_PREFIXES
        lower = letters.islower()
        if re.search(r'(?:github|twitter|facebook|instagram)'
                     r'\.com/[\w-]+\Z', text):
            value = -0.72 if token.isalpha() and lower else -0.27
        elif re.search(r'/(?:Users|home)/[\w-]+\Z', text):
            value = -0.9 if continuing and rare and lower else -0.4
        elif re.search(r'@[\w.-]+\Z', text):
            if continuing and lower:
                value = -0.60 if rare else -0.30
            else:
                value = -0.12
        elif re.search(r'(?i)(?:e-?mail|@?author)\s*[:=]?\s+[\w.-]+\Z', text):
            value = -0.5 if continuing and lower else -0.1
        elif lower and re.search(r'https?://\S+\Z', text):
            value = -0.5 if continuing and rare else -0.12
        elif lower and continuing and rare:
            line = tail.rsplit('\n', 1)[-1]
            if re.fullmatch('[a-z]+', line):
                value = -0.09
            elif not previous[:1].isspace():
                value = -0.03
            else:
                value = 0.0
        else:
            value = 0.0
    else:
        value = 0.0
    return state, value

"""Approximate a sparse multilingual yuan/won spelling response.

Positive pulses recognize Yuan, 원, Nguyen, and Chinese yuan homophones.
Dictionary meanings identify related Chinese compounds. Currency amounts
and Korean member/dimension suffixes get weaker pulses; Japanese cheering
gets a stronger one. Several other Latin y syllables get negative pulses.
The state holds only the previous token and unfinished UTF-8 bytes, and
resets at document boundaries. Unrecognized cases predict zero.
"""
from functools import lru_cache
import re
import codecs
from anyascii import anyascii
import cedict
import regex
from pypinyin import lazy_pinyin

READS = ()

# Pronounced yuan in Mandarin, except 円 (Japanese yen).
YUAN_CHARACTERS = {
    '原': 3.7,                 # original
    '源': 1.8,                 # source
    '渊': 3.0, '淵': 3.0,      # deep water
    '元': 4.5,                 # yuan / origin
    '袁': 6.0,                 # surname Yuan
    '援': 2.0,                 # aid
    '願': 2.7, '愿': 2.7,      # wish
    '円': 2.0,                 # yen
    '園': 1.4,                 # garden
    '圆': 0.8, '圓': 0.8,      # circle
}
CURRENCY_OR_UNIT_STEMS = {
    '美', '港', '澳', '欧', '歐', '单', '單', '方', '多', '次',
}

@lru_cache(maxsize=8192)
def chinese(s):
    if not regex.fullmatch(r'\p{Script=Han}+', s):
        return 0.0
    if len(s) > 1:
        if not any(ch in s for ch in '原源愿願'):
            return 0.0
        gloss = ' '.join(cedict.glosses(s)).lower()
        if '原' in s:
            if 'original text' in gloss or 'raw and semifinished' in gloss:
                return 3.0
            if any(w in gloss for w in ('plain', 'plateau', 'prairie')):
                return 2.0
            if 'cause' in gloss or 'atom' in gloss:
                return 1.2
        if '源' in s and 'energy' in gloss:
            return 0.9
        if (any(ch in s for ch in '愿願')
                and any(w in gloss for w in ('wish', 'willing'))):
            return 0.7
        return 0.0
    if s in YUAN_CHARACTERS:
        return YUAN_CHARACTERS[s]
    if lazy_pinyin(s) == ['yuan']:
        return 0.45
    return 0.0


def local_value(s, previous):
    v = chinese(s)
    if s == '元' and (previous.strip().isnumeric()
            or previous in CURRENCY_OR_UNIT_STEMS):
        return 0.8
    if s == '援' and previous.endswith(('応', '應')):
        return 7.0
    if v:
        return v
    if s.strip() == '원':
        if s.startswith(' '):
            return 8.2
        if previous.strip() == '회':       # 회원: member
            return 0.3
        if previous.strip() == '차':       # 차원: dimension
            return 1.2
        if previous.strip() == '자':       # 자원: resources
            return 7.0
        return 2.7 if previous.strip().isnumeric() or previous == '만' else 4.6
    if s.strip().lower() == 'yuan':
        return 6.0 if 'Y' in s else 2.4
    roman = anyascii(s).strip().lower()
    if roman == 'nguyen':
        if s.strip() == 'nguyện':
            return 2.7
        return 8.0 if not s.isascii() else 5.5
    if roman == 'uyen' and previous.strip().lower().endswith('ng'):
        return 8.5
    if s.strip() == 'yên':
        return 2.2
    if (re.fullmatch(r'[^a-zA-Z]*[yY]', previous)
            and s.isascii() and s.isalpha()):
