            return 9.0
        if s.lower().startswith('ue'):
            return 1.8
        if s.lower().startswith(('en', 'oon', 'eon')):
            return 0.8
        if s.lower() == 'up':
            return -4.5
        if re.fullmatch(r'[ou](?:[kp]|ck)', s.lower()):
