    _, previous, recent, age, prior_raw = carry
    s = prefix.token_strings[-1]
    value = estimate(s, previous, recent, age, prefix.token_bytes[-1], prior_raw)
    if s == '<|endoftext|>':
        previous, recent, age, prior_raw = '', '', 0, b''
    else:
        previous, recent, age = s, (recent + s)[-256:], age + 1
        prior_raw = (prior_raw + prefix.token_bytes[-1])[-8:]
    return (doc, previous, recent, age, prior_raw), value

programs.haiku:
"""Line-opening markers in code, markup and maths.

Layer-1 MLP unit 5007 reads the current token (and whether it opens a line)
and reports how strongly the token opens a structure. Its main pieces:

- Comment openers `//`, `#`, `##` (strong), and `import` in a `from x import y`
  line (strongest).
- Symbols that open a line: bullets, headings, rules (`•`, `` ` ``, `--`, `===`,
  `✓`, `§`) and the lone space that indents a code line. Mid-line symbols are ignored.
- Fragments of formulaic text: the word after `What is`, after `Let me` / `Let's`,
  the `{` in `\\begin{` and `\\end{`, the `</think>` tag, and non-breaking spaces.
- The double backslash `\\\\`: a LaTeX line break in maths is positive, and the
  same token inside a code string or regex (escaped quotes or `\\n`) is negative.

Everything else predicts zero. Values are typical activations, not fitted per token.
"""

import re

READS = ()
SYMBOL_MARKS = set("#/-•`*=_~§✓–—")
COMMENT_OPENERS = {"//", "#", "##", "###", "####", "//#"}
LATEX_COMMAND = re.compile(r"(?<!\\)\\[a-zA-Z]")


def _is_symbol(s):
    return s != "" and not any(c.isalnum() for c in s)


def _from_import(strings):
    """True if the newest token is `import` on a line that starts with `from`."""
    for tok in reversed(strings[:-1]):
        if "\n" in tok:
            return False
        if tok.strip() == "from":
            return True
    return False


def _after_escaped_newline(strings):
    """True if the token before is the `n` of a backslash-n written inside code."""
    return len(strings) > 2 and strings[-2].strip() == "n" and strings[-3].endswith("\\")


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1]
    s = tok.strip()
    before = strings[-2].strip() if len(strings) > 1 else ""
    line_start = len(strings) == 1 or "\n" in strings[-2] or _after_escaped_newline(strings)

    if s == "\\\\":
        window = "".join(strings[-12:-1])
        in_code = '\\"' in window or "\\n" in window or "\\r" in window
        in_maths = bool(LATEX_COMMAND.search(window)) or "&" in window
        return None, 3.0 if (in_maths and not in_code) else -1.1
    if s == "import":
        return None, 1.4 if _from_import(strings) else 0.0
    if s in COMMENT_OPENERS:
        return None, 0.7
    if s == "</think>":
        return None, 1.0
    if s == "{" and before in ("begin", "end"):
        return None, 1.2
    if before == "What" and s == "is":
        return None, 1.1
    if before == "Let" and s in ("me", "us", "'s", "’s"):
        return None, 0.6
    if tok == "\xa0":
        return None, 0.4
    if line_start and tok == " ":
        return None, 0.6
    if line_start and _is_symbol(s) and s[0] in SYMBOL_MARKS:
        return None, 0.5
    return None, 0.0

programs.sol:
"""Recognize metadata headers and the ends of written timestamps.

The opening Title colon is positive. Package names, document-preview labels,
Chinese news datelines, and timestamp endings are negative. Time-zone labels
after clocks including seconds have especially strong responses. All other
text receives zero; the last 100 characters provide bounded context.
"""
import re

READS = ()
ZONES = {'UTC', 'GMT', 'UT', 'EST', 'EDT', 'CST', 'CDT', 'MST', 'MDT',
         'PST', 'PDT', 'ET', 'CT', 'MT', 'PT', 'CET', 'CEST', 'BST'}
TIMESTAMP_ENDINGS = ZONES | {'Z', 'AM', 'PM', 'by', 'on', '#'}
CLOCK = re.compile(r'\d{1,2}[:.]\d{2}(?::\d{2})?')
END_CLOCK = re.compile(r'\d{1,2}:\d{2}(:\d{2})?(?:\.\d+)?\s*$')
MERIDIEM = re.compile(r'\d\s*(?:[AP]M|[ap]m|[ap]\.m\.)\s*\(?$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, text = 0, '', ''
    else:
        position, previous, text = carry[1] + 1, carry[2], carry[3]
    word = token.strip()
    value = 0.0
    if position == 1 and previous == 'Title' and token == ':':
        value = 15.0
    elif position == 1 and previous == 'package' and token == ' com':
        value = -2.64
    elif token == ' Document' and text.endswith('View Full'):
        value = -0.75
    elif token == '日电' and re.search(r'\d月\d{1,2}$', text):
        value = -2.8
    elif word in TIMESTAMP_ENDINGS:
        clock = END_CLOCK.search(text)
        meridiem = MERIDIEM.search(text)
        if word in {'AM', 'PM'} and clock:
            value = -0.6 if token.startswith(' ') else -0.3
        elif word == 'Z' and clock:
            value = -1.1
        elif word in ZONES and (CLOCK.search(text) or meridiem):
            if word in {'UTC', 'GMT', 'UT'}:
                if word == 'UT' or re.search(r'[+-]\d{4}\s*$', text):
                    value = -0.6
                elif clock or meridiem or END_CLOCK.search(text.rstrip(' (')):
                    value = -3.5
                else:
                    value = -1.5
            elif clock and clock.group(1):
                value = -10.5
            elif meridiem:
                value = -2.2 if '.' in meridiem.group() else -4.5
            elif clock:
                value = -3.2
            elif re.search(r'\d{2}\s*\([CEMP]$', text):
                # The last token can be only part of a zone, as in C + ET.
                value = -2.5
        elif word == 'by' and (clock or meridiem):
            value = -5.5 if meridiem else -4.0
        elif (word == 'on' and meridiem and CLOCK.search(text[-20:])
              and '.' not in meridiem.group()):
            value = -1.3
        elif word == '#' and meridiem:
            value = -1.55
    return (doc, position, token, (text + token)[-100:]), value

"""Approximate the component's large document-onset response.

The first token, and repetitions of it before any different token appears,
receive an onset value. Character type sets its scale; for Latin text,
longer and less frequent words tend to get larger values. Away from onset,
only a few opening-delimiter shapes receive small positive responses.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=4096)
def onset_value(s):
    t = s.strip()
    if t.startswith('<|'):
        return 14.0
    if t.isdecimal():
        return 4.6
    if not t:
        if '\t' in s:
            return 9.8
        if '\n' in s or '\r' in s:
            return 2.4
        return 3.9 if len(s) == 1 else 6.4
    letters = ''.join(c for c in t if c.isalpha())
    if not letters:
        category = unicodedata.category(t[0])
        if category in ('Ps', 'Pe'):
            return 5.7
        if category.startswith('S') or category == 'Pc':
            return 6.8
        return 9.0 if '\ufffd' in s else 3.2
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', letters):
        return 9.0
    if not regex.search(r'\p{Script=Latin}', letters):
        return 11.8
    if len(letters) == 1:
        return 10.2
    frequency = zipf_frequency(t.lower(), 'en')
    discount = (4.3 if frequency >= 7 else 2.4 if frequency >= 6
                else 1.2 if frequency >= 5 else 0.4)
    return 12.0 + 0.35 * min(len(letters), 8) - discount - 0.5 * s.startswith(' ')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, onset = token, True
    else:
        first, onset = carry[1], carry[2] and token == carry[1]
    s = prefix.token_strings[-1]
    value = 0.0
    if onset:
        value = onset_value(s)
    elif s == '{"':
        value = 0.8
    elif s.lstrip().startswith(('(', '[')) and ('\n' in s or '\\' in s):
        value = 0.5
    elif s.lstrip().startswith('{') and ('\n' in s or '\\' in s):
        value = 0.3
    return (doc, first, onset), value

programs.haiku:
"""Layer-1 MLP output feature 5010: a Chinese-character (CJK ideograph) detector.

The component writes into the residual stream on the token that puts a Chinese,
Japanese or other CJK ideograph (汉字) into the text, and on the UTF-8 byte pieces
that complete one. Strength depends on what the character is:

  * a single content ideograph (委, 輔, 水, 场, 人)          -> about 1.2
  * a two-character content word (开户, 讲师, 参考)          -> about 0.9
  * a longer ideograph word, three or more characters        -> about 0.5
  * a grammar word: 的 是 我 了 这个 我们 如果 但是 ...      -> weak (0.3 or 0.05)
  * a byte piece that completes an ideograph (the last UTF-8 byte of a split character)
                                                            -> strongest, about 1.8
  * a byte piece that starts or middles an ideograph          -> about 0.45
  * a whole Hangul syllable                                  -> about 0.6
  * a byte piece completing some other script                -> about 0.2
  * tool/thinking markup: <tool_call> 1.0, </tool_response> 0.6, </think> 0.5, </tool_call> 0.3
  * everything else (Latin, digits, punctuation, kana, spaces) -> 0

The program is stateless: each value depends only on the current token and, for byte
pieces, on the text decoded so far. Values are rounded group means measured on training
rows; the within-group spread (about 0.5 for ideographs) is token-specific and not modelled.
"""

import unicodedata

READS = ()

# Common grammar words written in ideographs: they fire weakly.
GRAMMAR = {
    "的", "是", "这", "那", "我", "你", "他", "她", "它", "们", "了", "吗", "呢", "吧",
    "也", "都", "就", "很", "在", "和", "而", "但", "如", "之", "其", "着", "个",
    "这个", "那个", "一个", "我们", "他们", "这些", "这样", "如果", "但是", "而且",
    "所以", "因为", "可以", "就是", "这是", "的是", "也是", "了一个",
}

MARKUP = {"<tool_call>": 1.0, "</tool_response>": 0.6, "</think>": 0.5, "</tool_call>": 0.3}


def _script(ch):
    name = unicodedata.name(ch, "")
    if "CJK" in name:
        return "han"
    if "HANGUL" in name:
        return "hangul"
    return "other"


def _end_script(text):
    """Script of the last decoded character; 'partial' if it is still U+FFFD."""
    text = text.rstrip()
    if not text:
        return None
    if text[-1] == "�":
        return "partial"
    return _script(text[-1])


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in MARKUP:
        return carry, MARKUP[tok]
    if "�" in tok:
        # A byte piece. Look at the text decoded through this token: if it now ends in
        # a real character, this piece completed one.
        end = _end_script(prefix.text_prefixes[prefix.position])
        if end == "han":
            return carry, 1.8
        if end == "partial":
            return carry, 0.45
        if end == "hangul":
            return carry, 0.6
        return carry, 0.2
    if not tok:
        return carry, 0.0
    scripts = {_script(ch) for ch in tok}
    if "han" in scripts:
        if tok in GRAMMAR:
            return carry, 0.3 if len(tok) == 1 else 0.05
        return carry, (1.2, 0.9, 0.5)[min(len(tok), 3) - 1]
    if "hangul" in scripts:
        return carry, 0.6
    return carry, 0.0

programs.sol:
"""A spelling-sensitive s/sh-to-r detector, not a general certainty detector.

Recognize spellings like sure, sir, shore and sorry, and
recognize the same transition when it straddles tokens.  S-to-p transitions
have the opposite sign.  'Make sure' suppresses the response; negation
reduces it. Predicative 'certain' gets a smaller positive response.
Values are approximate strengths measured on training text.
"""
import re
from anyascii import anyascii

READS = ()


def response(token, previous, context):
    word = token.strip()
    low = word.lower()
    before = previous.strip().lower()
    if low == 'sure':
        if not token[0].isspace() and previous[-1:].isalpha():
            return 0.3
        if before in ('make', 'makes', 'making', 'made'):
            return 0.05
        negation = r"(?:\bnot|n't|n’t)\s*(?:quite|really|even|exactly)?\s*$"
        if re.search(negation, context):
            return 1.15
        if before == 'pretty':
            return 1.4
        if before in ('quite', 'as', 'seems', '%'):
            return 2.6
        if word == 'Sure':
            return 5.45 if token[0].isspace() else 8.15
        if before == 'you':
            return 6.8
        if before == 'for':
            return 5.1
        if before == 'be':
            return 3.9
        if before in ('am', 'm', 'was', 'is'):
            return 3.8
        return 5.1
    if low == 'certain':
        return 1.7 if before in ('is', 'are', 'was', 'were', 'be',
                                'am', 'almost', 'absolutely') else 0.0
    if low == 'sir':
        return 5.0 if word == 'Sir' and token[0].isspace() else 3.9
    if low in ('shore', 'shores'):
        return (6.7 if word[0].isupper() else
                4.6 if low.endswith('s') else 3.5)
    if low == 'sorry':
        return 3.5
    if low in ('surely', 'unsure'):
        return 1.5 if low == 'surely' else 0.55
    if low == 'sore':
        return 2.45
    if low in ('sur', '-sur', 'sor', 'sr', 'sri', 'sire', 'shire', 'shr'):
        if low == '-sur':
            return 2.7
        if low == 'sur':
            english_words = r'\b(the|a|are|is|was|and|of|with|for|to|you)\b'
            english = re.search(english_words, context)
            return 2.8 if english else 0.4 if word == 'sur' else 1.9
        if low in ('sor', 'sr'):
            return 1.4
        return 2.1 if low in ('sri', 'sire') else 0.5
    if low in ('sip', 'sap', 'sop'):
        strength = -2.8 if low == 'sip' else -1.7 if low == 'sap' else -1.3
        return strength * (1.8 if word.isupper() else 1.0)
    if token[0].isspace():
        return 0.0

    # Transliteration makes the seam rule apply to Cyrillic and Arabic too.
    current = anyascii(token).lower()
    prev = anyascii(previous).lower()
    if prev.endswith('ts'):
        return 0.0
    if previous.lower() == 'h' and context.endswith('sh'):
        prev = 'sh'
    if not prev.endswith(('s', 'sh', 'x')):
        return 0.0
    initial_s = previous.lower().strip(' /-.(') == 's'
    if current == 'ure':
        return 8.2 if initial_s else 3.5
    if current == 'ore':
        return 1.3 if prev.endswith('ss') else 6.0
    if current == 'ores':
        return 5.0 if prev.endswith('sh') else 3.0
    if current == 'ir':
        return 5.8 if initial_s else 4.8
    if current == 'uration':
        return 6.4
    if current == 'ura':
        return 6.8 if initial_s else 4.0
    if current == 'ural':
        return 2.6
    if current in ('ur', 'yur'):
        return 3.7
    if current == 'r':
        return 0.0 if prev.endswith('x') else 3.5
    if current == 'ra' and prev.endswith('sh'):
        return 4.0
    if current in ('or', 'ra', 'ri', 'ro', 'ira', 'ire', 'aur', 'ouro', 'uri'):
        return 3.8 if current == 'uri' else 1.8
    if current in ('ors', 'ort', 'ures', 'ured'):
        return 0.9
    if re.fullmatch(r'[aio]p(?:h|ping)?', current):
        if prev.endswith(('sh', 'x')):
            return -0.4
        if current.endswith('ph'):
            return -1.0
        strength = -2.2 if current == 'ap' else -3.0
        return strength * (2.0 if token.isupper() else 1.0)
    if current == 'up':
        return -0.8
    # Longer word fragments give a much weaker spelling cue.
    if re.match(r'^[iou]?r', current):
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, context = '', ''
    else:
        _, previous, context = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, context) if token else 0.0
    return (doc, token, (context + token.lower())[-100:]), value

programs.haiku:
"""Word-level program for layers.1.mlp.down_proj:5013.

The component reads the spelling of the current word. It is large and positive when the
word so far is a form of 'sure', 'sir', 'sorry' or 'shore' (also when that spelling is split
over subword pieces, e.g. 's' + 'ure' in 'surefire', or 'nas' + 'ir' in 'Nasir'). It is
weakly negative on s-words with a short vowel and p or ss (sip, sap, sop, sass).
'make sure' (imperative) and 'not sure' are damped.
"""
READS = ()

WEIGHT = {
    "sir": 4.5, "shore": 4.3, "sorry": 3.5, "sire": 2.6, "sore": 2.4, "sri": 2.0,
    "shir": 2.0, "sure": 5.0, "surely": 1.5, "sr": 1.5, "sor": 1.3, "sur": 1.0,
}
NEGATIVE = {"sip": -3.0, "sap": -2.0, "sop": -1.3, "sass": -3.0}
WEAK_BEFORE = {"make", "making", "makes"}   # "make sure"
MEH_BEFORE = {"not", "quite", "pretty", "even"}  # "not sure"
FRAGMENT = 0.6   # the spelling completed inside a longer word, split over pieces


def current_word(strings):
    """The word so far (lowercase) and the index of its first piece."""
    k = len(strings) - 1
    word = ""
    while k >= 0:
        s = strings[k]
        if s[:1].isspace():
            word = s + word
            break
        if not s.isalpha():
            break
        word = s + word
        k -= 1
    start = k if (k >= 0 and strings[k][:1].isspace()) else k + 1
    return word.strip().lower(), start


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word, start = current_word(strings)
    pieces = len(strings) - start
    value = 0.0
    if word in WEIGHT:
        value = WEIGHT[word]
    elif word in NEGATIVE:
        value = NEGATIVE[word]
    elif pieces > 1:
        for trig, w in WEIGHT.items():
            if word.endswith(trig):
                value = FRAGMENT * w
                break
    if word == "sure" and value > 0 and start > 0:
        before = strings[start - 1].strip().lower()
        if before in WEAK_BEFORE:
            value *= 0.1
        elif before in MEH_BEFORE:
            value *= 0.25
    return carry, float(value)

programs.sol:
"""Recognize explicit self parameters, self compounds, and customization.

The dominant positive response is the delimiter after a Python/Rust instance or class
parameter, especially a comma in a method definition. The exact punctuation
and whether `(` shares the self token matter. Smaller rules cover Rust's
`Self::`, PHP's `self::$`, self-hosting/reporting and self-inter... compounds,
and English/Chinese customization. A separate small positive mode covers
the Japanese kana ma and made. Other activations are left at zero.
"""
import re

READS = ()
METHOD = re.compile(r'\b(?:def|fn)\s+[^()\n]+\([^()]*$')

# Hiragana ma, made (until), and katakana ma.
JAPANESE_MA = {
    'ま': 2.5,
    'まで': 1.6,
    'マ': 0.75,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    value = 0.0
    name = previous.strip()
    if name in ('self', '(self', 'cls'):
        method = bool(METHOD.search(text))
        if token == ',':
            if method:
                value = 13.2 if name == '(self' else 10.7
                if previous == ' self':
                    value = 9.0
            elif name == '(self':
                value = 6.1  # self supplied as an ordinary call argument
        elif token == ',\n':
            value = 6.5 if method else 3.5
        elif token == ')':
            value = 6.5 if method else 0.0
        elif token.startswith('):\n'):
            value = 4.1
        elif token.startswith('):\\'):
            value = 0.6
        elif token == '`':
            value = 1.0
        elif token.startswith('::$'):
            value = -4.5
        elif name != 'cls':
            if token.startswith('-host'):
                value = -9.0
            elif token.startswith('-report'):
                value = -5.3
            elif token.startswith('-inter'):
                value = 3.9
    if name in ('Self', '<Self'):
        if token == '::':
            value = -2.2
        elif token == ')':
            value = 1.6
        elif token == ' {\n':
            value = 1.1
        elif token.strip().startswith('Host'):
            value = -5.2
    if text.lower().endswith('self-host') and token == 'ed':
        value = -3.6
    if token.strip(' _./-').lower() == 'custom':
        value = -2.0
    # Customization: 自定义 / 自定義, including split final characters.
    if (token in ('定义', '定義') and text.endswith('自') or
            token in ('义', '義') and text.endswith('自定')):
        value = -8.0
    if token in JAPANESE_MA:
        value = JAPANESE_MA[token]
    return (doc, token, (text + token)[-200:]), value

programs.haiku:
"""Draft 4: at the first token of each document, predict the activation from the token's
character class (measured means): capitalised/lower-case ASCII word starts negative, code
punctuation starts positive, everything else near zero. All later positions predict 0."""
READS = ()
CODE_START = set("#/<{}[]()\\*$@'\"")

def step(carry, prefix, upstream):
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    t = prefix.token_strings[-1].strip()
    if t == "":
        return None, -0.04
    c = t[0]
    if c in CODE_START:
        return None, 0.11
    if c.isalpha():
        return None, -0.25
    if c.isdigit():
        return None, -0.1
    return None, 0.0

programs.sol:
"""A sparse collection of lexical and formatting cues, not one semantic rule.

The largest ordinary-language cue is German 'es' (it), distinguished from
Spanish 'es' by recent function words. Other cues are diff hunk headers,
PHP tags, digit 5 in names or after a space, and a few document openings.
Only an opening run of carriage returns gets the large carriage-return
response; progress updates later in a document do not. Unhandled tokens
get zero. The numeric opening '12' is an explicit exceptional response.
"""
import re

READS = ()
GERMAN = set((
    'der die das den dem des und nicht ist mit ein eine einer einem '
    'einen eines zu zum zur im am vom von für auf aus bei sich auch '
    'als wie oder aber noch wird werden wurde war waren kann hat '
    'haben wir er sie ihr ihm ihn ich du gibt'
).split())
SPANISH = set((
    'el la los las un una unos unas y que no en por para del al con '
    'se su sus como más pero está son hay'
).split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, opening_returns = '', True
    else:
        _, tail, opening_returns = carry
    token = prefix.token_strings[-1]
    value = 0.0

    # Bare 'es' is a word only at a boundary, not inside e.g. 'jedes'.
    word_es = token in (' es', ' Es') or (
        token in ('es', 'Es') and (not tail or not tail[-1].isalpha())
    )
    if word_es:
        words = re.findall(r'[^\W\d_]+', tail.lower())
        german = sum(w in GERMAN for w in words)
        spanish = sum(w in SPANISH for w in words)
        value = 0.12 if token.startswith(' ') else 0.0
        if german > spanish:
            value = 1.06 if token.startswith(' ') else 0.80
            if tail.endswith((' gibt', ' gab')):
                value = 0.61
    elif token == ' -' and tail.endswith('@@'):
        value = 1.10
    elif token == 'php' and tail.endswith('<?'):
        value = 4.49 if tail == '<?' else 1.25
        if tail[-3:-2] in ("'", '"'):
            value = 0.65
    elif token == '5':
        if tail[-1:].isascii() and tail[-1:].isalpha():
            value = 0.30
        elif tail.endswith(' '):
            value = 0.09
    elif token == '#!/' and not tail:
        value = -1.27
    elif token in ('/bash', '/sh') and tail == '#!/bin':
        value = 0.74
    elif token == ' "' and tail == '#include':
        value = 0.79
    elif token == '2' and tail == '1':
        value = 3.46
    elif token == '\r' and opening_returns:
        value = 2.93

    opening_returns = opening_returns and not token.strip('\r')
    return (doc, (tail + token)[-400:], opening_returns), value

"""Recognize structural separators, filenames and source-location diagnostics.

Most text receives a near-zero prediction. Colons, source-file endings,
GitHub hostnames and closing markup tags get positive pulses. A short text
suffix distinguishes diagnostic line numbers from ordinary labels and code.
Smaller rules cover traceback markers, imports, dividers and heading endings.
The state is discarded at document boundaries.
"""
import re

READS = ()
SOURCE = set(
    'py rs js ts jsx tsx go java php sh cpp cc cxx cs rb swift kt scala'.split()
)
DATA = set('json yaml yml xml mod conf ini toml sql jar properties'.split())
DOCUMENT = set('md txt html htm pdf rst'.split())
MEDIA = set('png jpg jpeg gif svg webp mp3 mp4 wav'.split())
C_HEADERS = set(
    'stdio stdlib string math time assert errno limits stdint stddef stdbool'.split()
)
LOCATION = re.compile(
    r'\.(?:' + '|'.join(sorted(SOURCE | {'c', 'h'})) + r')(?::\d+)*$'
)

# Rounded training means for readable, disjoint cases, not token identities.
LEVEL = {
    'ordinary': 0.0, 'colon': 0.43,
    'rust': 2.09, 'colon_double': 0.33,
    'end_message': 0.11, 'json_open': 0.27,
    'colon_quoted': -0.03, 'user_header': 0.22,
    'colon_newline': 0.35, 'domain': 0.14,
    'heading_end': 0.17, 'colon_diagnostic': 0.97,
    'python': 1.79, 'colon_source': 3.4,
    'location_digit': 1.19, 'colon_line': 1.9,
    'python_dunder': 2.71, 'colon_type': 0.07,
    'c_other': 0.01, 'data': 1.19,
    'import': 0.68, 'colon_space': 0.28,
    'colon_object': 0.15, 'divider': 0.27,
    'document': 0.57, 'comment_type': 0.98,
    'source': 1.15, 'colon_fullwidth': 0.4,
    'c_path': 1.0, 'c_standard_header': -0.29,
    'close_tag': 1.07, 'c_header': 0.33,
    'github': 2.84, 'github_url': 3.9,
    'media': 0.47, 'diff_header': 0.43,
    'close_summary': 1.58, 'open_summary': -0.42,
    'middle_dots': 1.4, 'initial_import': 1.02,
    'trace_line': 2.1, 'trace_in': 2.2,
    'python_packages': 2.5, 'close_heading_digit': 1.9,
    'filename_heading': 0.89, 'location_column_digit': 0.4,
}


def category(s, previous, tail):
    bare = s.strip()
    if s == '-packages' and tail.endswith(('/site', '/dist')):
        return 'python_packages'
    if s == ' line' and re.search(r'\.\w+(?:[\"\'],?)?$', tail):
        return 'trace_line'
    if s == ' in' and re.search(r'\.py(?:[\"\'], line \d+,)?$', tail):
        return 'trace_in'
    if s.isdigit() and re.search(r'</h$', tail):
        return 'close_heading_digit'
    if bare == '<|im_end|>':
        return 'end_message'
    if bare and set(bare) == {'·'} and len(bare) > 1:
        return 'middle_dots'
    if s == '\n' and tail.endswith('<|im_start|>user'):
        return 'user_header'
    if s == '\n' and re.search(r'(?:^|\n\n)[A-Z][A-Za-z ]{2,35}$', tail):
        return 'heading_end'
    if tail.endswith('</') and re.fullmatch(r'[A-Za-z][A-Za-z0-9]*', s):
        return 'close_summary' if s == 'summary' else 'close_tag'
    if tail.endswith('<') and s == 'summary':
        return 'open_summary'
    if s == 'import':
        if not tail:
            return 'initial_import'
        if previous.rstrip().endswith(';'):
            return 'import'
    if s == '{"':
        return 'json_open'
    if bare and len(bare) >= 3 and (set(bare) <= {'='} or set(bare) <= {'-'}):
        return 'divider'
    if bare == '@@':
        return 'diff_header'
    if bare == '{' and re.search(r'@(?:param|returns?|type)\s*$', tail):
        return 'comment_type'

    # The extension can be one token, or follow a separate dot token.
    extension = ''
    if s.startswith('.'):
        extension = s[1:]
    elif tail.endswith('.'):
        extension = s
    if extension.isalpha():
        e = extension.lower()
        if e == 'com':
            if tail.lower().endswith('.githubusercontent'):
                return 'github_url'
            if re.search(r'(?<![A-Za-z0-9_.])github$', tail.lower()):
                url = '://' in tail[-30:] or previous.startswith('"')
                return 'github_url' if url else 'github'
            return 'domain'
        if e in {'org', 'net', 'edu', 'io'} and s.startswith('.'):
            return 'domain'
        if e == 'py':
            return 'python_dunder' if tail.endswith('__.') else 'python'
        if e == 'rs':
            return 'rust'
        if e in SOURCE:
            return 'source'
        if e in DATA:
            return 'data'
        if e in DOCUMENT:
            return 'document'
        if e in MEDIA:
            return 'media'
        if e in {'c', 'h', 'r'}:
            stem = re.search(r'([A-Za-z_]+)$', tail)
            if e == 'h' and stem and stem[1] in C_HEADERS:
                return 'c_standard_header'
            if '#include' in tail.rsplit('\n', 1)[-1]:
                return 'c_header'
            if re.search(r'[/\\][^\s]*$', tail):
                return 'c_path'
            return 'c_other'

    # File:line:column is much stronger than an ordinary prose colon.
    if s.isdigit() and len(s) == 1 and previous == ':':
        match = LOCATION.search(tail[:-1])
        if match:
            if ':' in match[0]:
                return 'location_column_digit'
            return 'location_digit'
    if ':' in s or '：' in s:
        if re.fullmatch(r'[^A-Za-z0-9]*[:：][\s\\]*', s):
            if '"' in s or "'" in s or tail.endswith(('"', "'")):
                return 'colon_quoted'
            if '：' in s:
                return 'colon_fullwidth'
            if s.count(':') > 1:
                return 'colon_double'
            location = LOCATION.search(tail)
            if location and bare == ':':
                if '\n' in s:
                    return 'filename_heading'
                return 'colon_line' if ':' in location[0] else 'colon_source'
            if s.startswith(' '):
                return 'colon_space'
            line = tail.rsplit('\n', 1)[-1]
            if re.search(r'(?:Error|Warning|PASS|FAIL|Exception)$', tail):
                return 'colon_diagnostic'
            if re.search(r'\b(?:def|lambda)\b', line):
                return 'colon_type'
            in_braces = tail.rfind('{') > tail.rfind('}')
            if in_braces and re.search(r'[\w-]+$', tail):
                return 'colon_object'
            return 'colon_newline' if '\n' in s else 'colon'
    return 'ordinary'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail, previous = carry if carry is not None else (None, '', '')
    if doc != old_doc:
        tail, previous = '', ''
    s = prefix.token_strings[-1]
    value = LEVEL[category(s, previous, tail)]
    return (doc, (tail + s)[-240:], s), value

programs.haiku:
"""layers.1.mlp.down_proj:5018, a "source-file location" detector.

What it does: fires on the text that points at a source or data file and at the
location punctuation that follows it, as in compiler errors, stack traces and test logs.
  - a file extension such as `.rs`, `.go`, `.py`, `.js`, `.php` (or `py` after a dot in
    `__init__.py`): moderate, about 1.3;
  - the colon or parenthesis right after such an extension (`validator.go:456`,
    `FileLoader.php(66)`): strong, about 3.2;
  - `.com` right after `github` (`github.com/...`): strong, about 3.7;
  - the `::`, `:/`, `:\n` or ` (` right after an extension: weaker, about 1.0;
  - ` in` inside a traceback line (`File "x.py", line 12, in f`) and `::` shortly after
    a file name: about 1.5.
Secondary, weaker responses: a colon after a diagnostic word (`warning:`, `FAIL:`, `PASS:`)
about 1.5; a plain colon about 0.45; a colon ending a line about 0.4; HTML table tags
`td`, `th`, `tr` about 0.6; markdown rule lines `---`, `===` about 0.5; backtick code marks
about 0.3. Everything else predicts 0.

The program is stateless: it reads only the newest tokens of the prefix.
"""

READS = ()

# Extensions of source and data files, as they appear in paths and error messages.
FILE_EXTENSIONS = {".rs", ".go", ".py", ".js", ".ts", ".jar", ".mod", ".yml", ".vue", ".php",
                   ".java", ".json", ".xml", ".md", ".txt", ".sh", ".so", ".a"}
# The same extensions as a bare token after a dot, as in "__init__." + "py".
BARE_EXTENSIONS = {"rs", "go", "py", "js", "ts", "jar", "mod", "yml", "vue", "php", "java",
                   "json", "xml", "md", "txt", "sh", "so"}
DIAGNOSTIC_LABELS = {"warning", "error", "note", "help", "FAIL", "PASS", "Warning", "Error",
                     "Note", "DeprecationWarning", "ERROR", "WARNING"}
TABLE_TAGS = {"td", "th", "tr"}
CODE_MARKS = {"`", " `"}
RULE_LINES = {"---", "===", " ---"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    before = toks[-8:-1]

    # A file extension, either as one token (".py") or a bare name after a dot.
    if cur in FILE_EXTENSIONS or (cur in BARE_EXTENSIONS and prev == "."):
        return carry, 1.3
    # "github.com", possibly split as "\tg" + "ithub" + ".com".
    if cur == ".com" and "".join(toks[-3:-1]).endswith("github"):
        return carry, 3.7
    # Location punctuation right after a file name: "file.go:12", "File.php(66)".
    after_file = prev in FILE_EXTENSIONS or (prev in BARE_EXTENSIONS and toks[-3:-2] == ["."])
    if after_file and cur in (":", "("):
        return carry, 3.2
    if after_file and cur in ("::", ":\n", ":/", " ("):
        return carry, 1.0
    # Traceback wording: 'File "x.py", line 12, in f'.
    if cur == " in" and " line" in before and any(s in FILE_EXTENSIONS for s in before):
        return carry, 1.5
    if cur == "::" and any(s in FILE_EXTENSIONS for s in toks[-4:-1]):
        return carry, 1.5
    # Other colons: after a diagnostic word, or a plain colon.
    if cur == ":":
        if prev.strip() in DIAGNOSTIC_LABELS:
            return carry, 1.5
        return carry, 0.45
    if cur in (":\n", ":\n\n"):
        return carry, 0.4
    if cur in TABLE_TAGS:
        return carry, 0.6
    if cur in RULE_LINES:
        return carry, 0.5
    if cur in CODE_MARKS:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""Numeric periods and single-space endings of whitespace runs.

Standalone periods after short integers give a negative response, especially
zero and one. Fractional endings, list labels and four-digit numbers are
weaker. Preceding symbols and nearby decimals adjust the strength. A single
space extending other spaces is also negative. A line-start `import` following
a semicolon is positive. Other tokens are approximately silent.
"""
import re

READS = ()


def numeric_period(tail, line):
    match = re.search(r'[0-9]+$', tail)
    if not match:
        return -0.02
    digits = match.group()
    before = tail[:match.start()]
    n = len(digits)
    if before.endswith('.'):
        return -0.3 if n == 1 else -0.05
    if line.strip() == digits and not digits.startswith('0'):
        return -0.1 if len(line) <= 2 else -0.65

    # Baseline by integer length; zero and one get extra weight.
    value = (-1.6, -1.2, -1.0, -0.3, -0.5)[min(n, 5) - 1]
    value -= {'0': 0.75, '1': 0.4}.get(digits, 0.0)
    symbol = before[-1:]
    if symbol and symbol in '$£€¥₹₩':
        value -= 1.2
    elif symbol and symbol in '([':
        value -= 0.6
    elif symbol == '_':
        value -= 0.55
    elif symbol and symbol in '=*/^×÷':
        value += 0.4

    context = before[-100:]
    decimals = len(re.findall(r'[0-9]\.[0-9]', context))
    sentences = len(re.findall(r'[A-Za-z][.!?]', context))
    value -= 0.3 * min(decimals, 3)
    value += 0.13 * min(sentences, 3)
    return max(-5.5, min(value, 0.1))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, tail, position = carry
    token = prefix.token_strings[-1]
    line = tail.rsplit('\n', 1)[-1]
    value = 0.0
    if token == '.':
        value = numeric_period(tail, line)
    elif token == ' ':
        spaces = len(tail) - len(tail.rstrip(' '))
        if spaces == 1:
            value = -1.0 if not line.strip() else -0.78
        elif spaces > 1:
            value = -1.3 if spaces <= 4 else -1.08
            if position < 50:
                value -= 0.2
    elif token == 'import' and not line.strip():
        if position == 0:
            value = -0.8
        elif tail.rstrip().endswith(';'):
            value = 1.5
    return (doc, (tail + token)[-300:], position + 1), value

"""Local English phrase fragments and document labels.

Positive responses mark 'problem/question/issue of', 'let us', negated
'yet/much', personal reflexives, and question/answer numbering labels.
'Step by' (especially hyphenated) has the opposite sign. Document-opening
labels receive a larger response. A few split-word completions are also
recognized. This approximates the conspicuous peaks, not the smaller
token-specific fluctuations; uncovered tokens stay near zero.
"""
import re

READS = ()

# Responses after these topic/procedure nouns: ordinary / preceded by "the".
OF_PHRASES = {
    'problem': (1.2, 3.4), 'question': (1.7, 2.45),
    'issue': (1.0, 1.65), 'case': (0.45, 1.15),
    'process': (0.2, 0.65), 'example': (0.7, 0.7),
    'formula': (0.8, 0.8), 'challenge': (0.7, 0.7),
    'technique': (0.6, 0.6), 'method': (0.2, 0.2),
    'art': (0.45, 0.45), 'task': (0.6, 0.6),
}
PERSONAL_REFLEXIVES = {
    'myself': 0.44, 'yourself': 0.27, 'ourselves': 0.25,
    'himself': 0.04, 'herself': 0.07, 'themselves': 0.03,
    'itself': -0.15,
}
NUMBERED_LABELS = {
    'Answer': 4.5, 'Example': 3.5, 'Challenge': 3.5,
    'Reply': 1.8, 'TODO': 1.0, 'Option': 1.5,
    'Problems': 1.4, 'Route': 1.0,
}


def predict(s, previous, before_previous, tail, position):
    word = s.strip()
    prev = previous.strip()
    low = prev.lower()
    if s == ' of' or s == ' OF':
        match = re.search(r'([A-Za-z]+)$', tail)
        noun = match.group(1).lower() if match else ''
        if noun in OF_PHRASES:
            definite = before_previous.strip().lower() == 'the'
            return OF_PHRASES[noun][int(definite)]
        if noun.endswith('s') and noun[:-1] in OF_PHRASES:
            return OF_PHRASES[noun[:-1]][0] * 0.4
    if word in ('by', '-by') and low == 'step':
        return -2.0 if word == '-by' else -1.15
    if word == 'us' and low == 'let':
        return 1.7 if prev[:1].isupper() else 1.0
    if word == 'to' and low == 'how':
        if position <= 3 and (not before_previous or
                              before_previous.strip().startswith('#')):
            return 1.3 if position == 1 else 2.0
        return 0.3 if prev == 'How' else -0.13
    if word in ('yet', 'much'):
        direct_not = low == 'not' or prev in ("n't", '’t')
        negated = re.search(r"(?:\bnot\b|n't|n’t)[^.!?\n]{0,32}$",
                            tail, re.I)
        if word == 'yet':
            return 0.85 if direct_not else (0.2 if negated else -0.05)
        if direct_not:
            return 1.6
        if negated:
            return 0.65
        return {'so': 0.42, 'as': 0.25, 'that': 0.65,
                'too': 0.22, 'very': 0.16}.get(low, 0.0)
    if word in PERSONAL_REFLEXIVES:
        return PERSONAL_REFLEXIVES[word]
    if word == 'self' and not s.startswith(' '):
        match = re.search(r'([A-Za-z]+)$', tail)
        stem = match.group(1) if match else ''
        return {'my': 2.3, 'My': 1.8, 'your': 1.7,
                'it': 0.6, 'It': 0.7}.get(stem, 0.02)
    if word == 'self':
        return -0.09
    if word == '#' and re.search(r'\bMember\s*$', tail):
        return 1.6
    if word == '#' and prev in NUMBERED_LABELS:
        return NUMBERED_LABELS[prev]
    if word == '#' and re.search(r'\bQuestion\s*$', tail):
        return 8.5 if position == 2 else 4.5
    if prev == 'Question':
        if word == ':':
            if s.startswith(' '):
                return 6.0
            return 4.6 if position == 1 else 1.1
        if s == ' ':
            return 0.6
        if s == '\n\n' and re.search(r'(?:^|\n)Question$', tail):
            return 5.9 if position == 1 else 1.7
    if word == ':':
        if prev == 'Title':
            return 4.16 if position == 1 else 0.1
        if prev in ('Subject', 'Thread'):
            return 1.3
        if prev in ('Source', 'Task') and s.startswith(' '):
            return 1.4
    if word == 'php' and previous == '<?':
        return 1.9 if position == 1 else 0.4
    if word == 'else':
        return 0.6 if low == 'nothing' else -0.07
    if word == 'Source' and prev == 'Article':
        return 0.5
    if s == ' ' and prev == 'Problem':
        return 0.6
    # A few familiar words split just before their last syllable.
    if s == 'rough' and tail.lower().endswith('th'):
        return 1.2
    if s == 'us' and prev.lower() == 'vers':
        return 1.0
    if s == 'US' and previous == 'TH':
        return 3.0
    if position == 0 and word == 'Not':
        return 1.06
    return -0.05 if position == 0 else -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, prior, tail = 0, '', '', ''
    else:
        _, position, previous, prior, tail = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, prior, tail, position)
    carry = (doc, position + 1, s, previous, (tail + s)[-96:])
    return carry, float(value)

programs.haiku:
"""Fires on the token that follows a stock phrase or a label word, in a few specific
places:

* "of" right after a problem-type noun: "the problem of" (strongest), "the question of",
  "the issue of", "the case of", "an example of", "the process of".
* the "#" (or line break) that opens a numbered item right after "Question", "Answer",
  "Challenge", "Problem" (e.g. "Answer #3", or "Question" newline "#").
* the ":" after "Title", "Subject", "Question", "Topic" (a header colon).
* "us" in "Let us", "much" in "so much" / "not much", "self" in "myself"/"yourself".
* slightly negative on "by" in "step by step".

Everything else is predicted as 0. Values are the mean activation for each case.
"""

READS = ()

OF_NOUN = {"problem": 3.2, "question": 1.8, "issue": 1.4, "challenge": 0.9, "case": 0.9,
           "example": 0.6, "process": 0.5}
ITEM_WORD = {"Question", "Answer", "Challenge", "Problem", "Problems", "Reply", "Tip", "Route"}
HEADER_WORD = {"Title", "Subject", "Question", "Topic"}
MUCH_AFTER = {"so": 0.5, "as": 0.3, "not": 1.3, "that": 1.0}
SELF_AFTER = {"my": 2.3, "your": 2.3}


def step(carry, prefix, upstream):
    n = len(prefix)
    docs = prefix.document_ids
    strs = prefix.token_strings

    def back(k):
        # token k steps back, or "" if it lies in an earlier document
        if n > k and docs[-1 - k] == docs[-1]:
            return strs[-1 - k]
        return ""

    raw = strs[-1]
    cur = raw.strip()
    before = back(1)
    word = before.strip().lower()
    if cur == "of" and word in OF_NOUN:
        return carry, OF_NOUN[word]
    if before.strip() in ITEM_WORD and raw in ("#", " #", "\n\n"):
        return carry, 2.5
    if before == "\n\n" and raw == "#":
        return carry, 4.0 if back(2).strip() in ITEM_WORD else 0.7
    if before.strip() in HEADER_WORD and raw in (":", ":\n"):
        return carry, 1.0
    if cur == "much" and word in MUCH_AFTER:
        return carry, MUCH_AFTER[word]
    if cur == "us" and word == "let":
        return carry, 1.0
    if cur == "self" and word in SELF_AFTER:
        return carry, SELF_AFTER[word]
    if cur in ("by", "-by") and word == "step":
        return carry, -1.1
    return carry, 0.0

programs.sol:
"""Recognize method receivers, rather than ordinary mentions of `self`.

Python constructors, other special methods, and ordinary methods differ in
strength. Rust distinguishes owned, borrowed, and mutable borrowed receivers;
borrowing self in a body gives a smaller response. Small related responses mark
method decorators, context/request parameters, and **kwargs. Line breaks can
weaken a receiver response. Only a short text tail is remembered, resetting
at document boundaries; quoted JSON newlines are treated as code newlines.
"""
import re

READS = ()

PYTHON = re.compile(
    r"\bdef\s+(\w+)\s*\((\s*(?:\d+\t\s*)?)(self|cls)$"
)
RUST = re.compile(
    r"\bfn\s+[^(;{}]+\(\s*(?:\d+\t\s*)?"
    r"(&\s*)?(?:'\w+\s*)?(mut\s+)?self$"
)
RECEIVER_TOKEN = re.compile(r"^[^\w]*(?:self|cls)$")
BORROW = re.compile(r"(?<!&)&\s*(mut\s+)?self$")
CONTEXT = re.compile(
    r"(?:\bdef\s+\w+|\bfunc(?:\s+\w+)?)\s*\(\s*(request|ctx)$"
)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ""
    token = prefix.token_strings[-1]
    tail = (tail + token)[-500:]
    value = 0.0

    # Source code is also often quoted inside JSON strings.
    code = tail.replace("\\n", "\n").replace("\\t", "\t")
    if RECEIVER_TOKEN.fullmatch(token):
        method = PYTHON.search(code)
        rust = RUST.search(code)
        borrow = BORROW.search(code)
        if method:
            name, gap, receiver = method.groups()
            if receiver == "cls":
                value = 10.0
            elif name == "__init__":
                value = 14.1
            elif name.startswith("__") and name.endswith("__"):
                value = 19.5
            else:
                value = 16.9
            if "\n" in gap:
                value *= 0.5 if receiver == "cls" else 0.72
        elif rust:
            if rust[1]:
                value = 18.8 if rust[2] else 15.8
                if "\n" in rust[1] + (rust[2] or ""):
                    value *= 0.4
            else:
                value = 8.5
        elif borrow:
            value = 8.9 if borrow[1] else 5.0
        else:
            value = -0.35
    elif token.endswith(("request", "ctx")) and CONTEXT.search(code):
        value = 5.0 if token.endswith("request") else 3.0
    elif token == "(&" and re.search(r"\bfn\s+[^(;{}]+\(&$", code):
        value = 2.5
    elif token.strip() == "Self":
        value = -0.5  # Rust's receiver type, not the receiver argument.
    elif token == "mut" and re.search(r"&\s*mut$", tail):
        value = 1.4
    elif token.endswith("staticmethod") and tail.endswith("@staticmethod"):
        value = 4.0
    elif token.endswith("Override") and tail.endswith("@Override"):
        value = 1.25
    elif token == "kwargs" and tail.endswith("**kwargs"):
        value = 2.0

    return (document, tail), value

"""An opening-token pulse, continuing through identical opening tokens.

Pulse height depends mainly on character type, length and case. Short
alphabetic tokens tend to be stronger than long capitalized words;
whitespace and digits are weak. The title-cased definite article is a
negative exception; self-reference, forms of "be" and negation are strong.
Once a different token arrives, predict zero.
"""

import regex

READS = ()
SELF_REFERENCE = frozenset('i me my mine we us our ours'.split())
BE_FORMS = frozenset('am is are was were be been being'.split())
NEGATION = frozenset('not no never neither nor'.split())


def opening_height(text):
    word = text.strip()
    if text.startswith('<|'):
        return 13.4 if text == '<|endoftext|>' else 6.1
    if not word:
        return 1.0
    if word.isascii() and word.isdecimal():
        digit = int(word)
        if digit == 0:
            return -0.9
        if digit <= 2:
            return 2.5
        return 0.8 if digit <= 5 else -0.2
    if any(c.isalpha() for c in word):
        lower = word.lower()
        if lower == 'the':
            if word.istitle():
                return -1.5 if text == word else 2.9
            return 5.5
        if lower in SELF_REFERENCE | BE_FORMS | NEGATION:
            return 9.2
        if regex.search(r'\p{Script=Han}', word):
            return 7.2
        if len(word) <= 3:
            if word.isupper():
                return 4.7 if word.isascii() else 8.4
            return 7.1 if text.startswith(' ') else 8.3
        return 6.0 if word.islower() else 4.5
    if '\ufffd' in word:
        return 9.0  # isolated-token Unicode replacement
    if '\n' in text:
        return 0.6 if len(word) <= 1 else 2.1
    if not word.isascii():
        return 4.5
    if all(c in '.,;:!?' for c in word):
        return 3.5
    return 3.2 if text.startswith(' ') else 4.5


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    token = prefix.token_bytes[-1]
    if first or (carry is not None and carry == token):
        return token, opening_height(prefix.token_strings[-1])
    return None, 0.0

"""A sparse lexical/orthographic response, not a general person detector.

Chinese words for users, readers, netizens and reporters have negative
responses; so does the Thai consonant kho khwai. Vietnamese has additional
case-sensitive letter-fragment responses: negative initial g/k, positive qu/v
and some short rounded-vowel syllables. A fading memory of distinctive
Vietnamese diacritics gates those rules. Everything else is left near zero.
The rules intentionally omit arbitrary document-initial and rare byte effects.
"""
READS = ()

# Letters with Vietnamese-specific vowel/tone combinations. Ordinary accents
# such as French e-acute are not enough to switch on the Vietnamese rules.
VIETNAMESE_MARKS = frozenset(
    'ăđơưạảấầẩẫậắằẳẵặẹẻếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỷỵ'
)


def vietnamese_fragment(text):
    """Responses to short spelling fragments, with word-initial space kept."""
    lower = text.lower()
    word = lower.lstrip()
    initial = lower != word
    if initial:
        if word == 'g':
            return -2.3 if text.endswith('g') else -0.6
        if word == 'k':
            return -1.5 if text.endswith('k') else -1.0
        if word == 'v':
            return 1.25 if text.endswith('v') else 0.6
        if word == 'qu':
            return 1.1
        if word in {'qua', 'quy'}:
            return 0.6
        # Short x + open vowel fragments.
        if len(word) == 2 and word[0] == 'x' and word[1] in 'aeo':
            return 2.4
        # c/v followed by a rounded back vowel.
        if len(word) == 2 and word[0] in 'cv' and word[1] in 'oô':
            return 1.5 if text.lstrip()[0].islower() else 1.0
        if word in {'t', 'c', 'đ', 'ca'}:
            return 0.5 if text.lstrip()[0].islower() else 0.2
        if word == 'x':
            return 0.3 if text.endswith('x') else 0.0
        if word in {'ng', 'nh'}:
            return -0.2
    # A vowel emitted as a separate token inside a Vietnamese syllable.
    if lower == 'o':
        return 0.6
    if lower in {'i', 'u', 'ô'}:
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        evidence = 0.0
    else:
        evidence = carry[1] * 0.90
    text = prefix.token_strings[-1]
    if any(c in VIETNAMESE_MARKS for c in text.lower()):
        evidence = 1.0
    word = text.strip()

    if word == 'ค':  # Thai consonant kho khwai.
        value = -3.1
    elif word in {'用户', '用戶'}:
        value = -1.2 if text == word else -0.65
    elif word in {'使用者', '读者', '讀者', '网友', '網友'}:
        value = -0.9
    elif word in {'记者', '記者'}:
        value = -0.65
    elif word == '者':
        value = -0.1
    elif word.lower() == 'bạn':  # Vietnamese "you/friend".
        value = -1.35
    elif evidence > 0.15:
        value = vietnamese_fragment(text)
    else:
        value = 0.0
    return (document, evidence), value

"""A spelling-based approximation to short word-fragment endings.

Short vowel-ending continuations are positive; German-looking context raises
final-e responses. Common inflectional endings, vowel letters in other scripts,
and Katakana phonetic marks have related rules. Length and case damp responses.
The carry counts preceding letters and decaying German/English word evidence,
resetting at document boundaries. Partial UTF-8 tokens and repeated middle dots
are handled separately. This does not try to infer actual pronunciation.
"""
import unicodedata as ud
from functools import lru_cache
from wordfreq import zipf_frequency

READS: tuple[str, ...] = ()
VOWELS = 'aeiouyæøœıаеёиоуыэюяіїєъαεηιουω'


@lru_cache(maxsize=65536)
def spelling(t):
    s = t.strip()
    low = s.lower()
    z = ''.join(c for c in ud.normalize('NFD', low)
                if not ud.combining(c))
    names = [ud.name(c, '') for c in s]
    script = ''
    for name in ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC', 'KATAKANA', 'CJK'):
        if s and any(name in n for n in names) and all(
                     name in n or ud.category(c).startswith('M')
                     for n, c in zip(names, s)):
            script = name
            break
    en = zipf_frequency(low, 'en') if script == 'LATIN' else 0.
    de = zipf_frequency(low, 'de') if script == 'LATIN' else 0.
    evidence = 0
    if t.startswith(' ') and script == 'LATIN':
        if de >= 4 and de - en > 1:
            evidence = 1
        elif en >= 4 and en - de > 1:
            evidence = -1
    return s, z, script, en, de, evidence


def response(t, previous_length, german, raw=b''):
    s, z, script, en, de, _ = spelling(t)
    n = len(s)
    end = z[-1:] or ' '
    bare = t == s
    vowel = end in VOWELS and not s.lower().endswith('й')
    upper = s[:1].isupper()

    if n >= 2 and all(c == '·' for c in s):
        return 1.66
    if '\ufffd' in s:
        # UTF-8 continuation bytes belong to a character begun earlier.
        if t[:1].isspace():
            return -0.02
        if s.startswith('ー'):
            return 0.70
        if raw and 0x80 <= raw[0] < 0xC0:
            return 0.27 if len(raw) == 1 else (0.19 if len(raw) == 2 else 0.)
        return -0.03

    if script == 'LATIN' and bare and vowel:
        if german > 0.09:
            if end == 'e':
                return 0.97 if german > 0.54 else 0.59
            return 0.37 if n <= 2 else 0.23
        if not previous_length:
            return 0.02
        if upper:
            return 0.19 if n == 1 else 0.09
        if n == 1:
            return 0.64 if en < 3 else 0.49
        if end == 'y':
            return 0.08
        if n == 2:
            return 0.20 if end == 'o' else 0.39
        if n == 3:
            if previous_length > 4:
                return 0.16
            return 0.35 if end == 'e' else 0.24
        return 0.16 if n == 4 and en < 3.55 else 0.01

    if script == 'KATAKANA':
        return 0.65 if s in ('ー', 'ッ') else max(-0.10, 0.22 - 0.08 * n)

    if script in ('CYRILLIC', 'GREEK') and bare and vowel:
        if script == 'GREEK' and n == 1:
            return 0.60 if previous_length else 0.25
        if end == 'е':
            return 0.48
        if all(c in VOWELS for c in z):
            return 0.60 if previous_length >= 2 else 0.30
        return 0.30 if previous_length <= 4 else (0.18 if n <= 3 else 0.04)

    if script == 'ARABIC':
        if bare and all(ud.category(c).startswith('M') for c in s):
            return 0.60
        if bare and end in 'اويىةی':
            return 0.50 if n == 1 else 0.37
        return 0.13 if bare else -0.05

    if previous_length and script == 'LATIN' and bare:
        # Common English/German inflectional endings.
        if z in ('es', 'en'):
            return 0.24
        if z in ('s', 'ed', 'ing', 'er'):
            return 0.12
    if script == 'CYRILLIC' and bare and s.lower().endswith('й'):
        return 0.16 if n >= 2 else 0.03

    if not previous_length:
        if script == 'CYRILLIC':
            return -0.07
        if vowel and script == 'LATIN' and de - en > 1.75 and n >= 3:
            return 0.53
        return 0.016 if vowel else -0.005
    if script == 'CJK':
        return 0.0
    if n == 1:
        return 0.14
    if n <= 3 and previous_length <= 4:
        return 0.12 if end in 'lnrms' else 0.04
    return -0.13 if script == 'CYRILLIC' else -0.02


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0., 0., False)
    _, length, german_count, english_count, ends_letter = carry
    continuing = ends_letter and t[:1].isalpha()
    previous_length = min(length, 15) if continuing else 0
    s, _, _, _, _, evidence = spelling(t)
    german_count = .98 * german_count + (evidence > 0)
    english_count = .98 * english_count + (evidence < 0)
    german = max(0., (german_count - english_count) /
                 (german_count + english_count + 2))
    value = response(t, previous_length, german, prefix.token_bytes[-1])
    length = previous_length + len(s) if s.isalpha() else 0
    carry = (doc, length, german_count, english_count, t[-1:].isalpha())
    return carry, float(value)

programs.haiku:
"""Word fragments in alphabetic, inflected-language text: layers.1.mlp.down_proj:5024.

What the component does, measured on training text (activation = its contribution to
the layer-1 MLP output):

1. A continuation piece of a word. The token is letters only, has no leading space,
   and directly follows a token ending in a letter in the same document, so the word
   was split across tokens. Short pieces fire most: 1 letter ~0.21, 2 ~0.13, 3 ~0.10,
   4 ~0.04, 5 or more ~0. Pieces written in an alphabet get a value by script:
   accented Latin ~0.29, Greek ~0.38, Arabic ~0.22, Cyrillic ~0.13. Chinese, Japanese
   and Korean pieces get ~0.
2. A word cut across a character: a token that decodes to half a UTF-8 character
   (U+FFFD) gets ~0.15.
3. A German determiner or article written as a whole word after a space (die, eine,
   alle, beide, dieses, ...) gets ~0.67.
4. Everything else gets 0: whole words, punctuation, digits, spaces, and the
   activation's small negative and positive tails, which this program does not model.

Values are category means on training rows, so predictions sit on the component's
scale. The program uses only letter classes, script names and a short list of German
determiners; it does not use a table of token ids.
"""

import unicodedata

READS = ()

GERMAN_DETERMINERS = {
    "die", "Die", "eine", "alle", "beide", "dieses", "diese", "dieser", "welche",
    "ihre", "keine", "einige", "jede", "jeder", "viele", "andere", "einer", "eines",
}

SCRIPT_VALUE = {"LATIN": 0.29, "GREEK": 0.38, "ARABIC": 0.22, "CYRILLIC": 0.13}
SHORT_PIECE_VALUE = {1: 0.21, 2: 0.13, 3: 0.10, 4: 0.04}


def _value_of_piece(piece):
    if piece.isascii():
        return SHORT_PIECE_VALUE.get(len(piece), 0.0)
    scripts = {unicodedata.name(c, "?").split()[0] for c in piece if c.isalpha()}
    values = [SCRIPT_VALUE[s] for s in scripts if s in SCRIPT_VALUE]
    if values:
        return max(values)
    if scripts & {"CJK", "HIRAGANA", "KATAKANA", "HANGUL"}:
        return 0.0
    return 0.12


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    prev = ""
    if t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]:
        prev = prefix.token_strings[t - 1]
    value = 0.0
    if "�" in cur:
        value = 0.15
    elif cur.isalpha() and prev[-1:].isalpha():
        value = _value_of_piece(cur)
    elif cur.startswith(" ") and cur[1:] in GERMAN_DETERMINERS:
        value = 0.67
    return carry, float(value)

programs.sol:
"""Approximate title/quotation onsets, not ordinary sentence capitalization.

Article-like spellings, especially 'The', receive negative pulses when they
begin a phrase inside a sentence. A nearby book/film/publication cue or a
possessive strengthens this. Opening quotation marks behave similarly;
closing quotes and reported-speech introductions mostly do not. Small
positive baselines cover sentence starts and speech introductions. Recent
code delimiters suppress the quoted-title reading.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
LITERATURE = set('novel film book poem movie opera'.split())
WORKS = set('''song album track play series episode show newspaper magazine
article essay paper publication journal title documentary musical story
collection comedy drama video game letter work report record program
programme painting drawing thesis chapter manuscript document lyric
biography edition treatise ballad season sitcom band'''.split())
NAMING = set('''call name entitle title read write publish release sing pen
record review perform'''.split())
SPEECH = set('say ask tell state reply add explain'.split())
ARTICLES = set('''Le La Les El Los Las Der Die Das Ein Eine Un Une
De Het Een Il'''.split())
FOREIGN_WORKS = tuple('''livro libro livre roman filme canción 映画 节目
節目 电影 電影 电视剧 電視劇 文章 小说 小說'''.split())
QUOTES = {'"', '“', '``', '«', '„', "'", '‘', '`'}


@lru_cache(maxsize=16384)
def cue(word):
    """0: no cue; 1: work/naming cue; 2: book, film or literary work."""
    forms = set(wordnet.base_forms(word)) | {word}
    if forms & LITERATURE:
        return 2
    if (forms & (WORKS | NAMING) or word in FOREIGN_WORKS
            or any(word.endswith(w) for w in FOREIGN_WORKS
                   if not w.isascii())):
        return 1
    return 0


def predict(s, prev, text, start):
    t = s.strip()
    glued_quote = len(t) > 1 and t[0] in '"“«' and t[1].isupper()
    if glued_quote:
        t = t[1:]
    if start:
        if glued_quote:
            return -1.66
        if t == 'The':
            return 1.18
        return 0.30 if t[:1].isupper() else 0.0
    if not (t[:1].isupper() or t in QUOTES or t in {'《', '「', '『', '〈'}):
        return 0.0
    raw_words = re.findall(r'[^\W\d_]+', text)
    words = [w.lower() for w in raw_words]
    last = words[-1] if words else ''
    kind = cue(last)
    nearby = any(cue(w) for w in words[-4:])
    p = prev.strip()
    end = text.rstrip()[-1:] if not p else p[-1:]
    sentence = bool(end and end in '.!?')
    possessive = p in ("'s", '’s')
    author_of = bool(re.search(r'\bauthor of\s*$', text.lower()))
    foreign_work = last in FOREIGN_WORKS
    # Separate an author's possessive from contractions like "it's".
    owner = raw_words[-2] if possessive and len(raw_words) > 1 else ''
    named_owner = owner[:1].isupper()
    if t == 'The' or t in ARTICLES:
        scale = 1.0 if t == 'The' else 0.55
        if not glued_quote:
            if sentence:
                return 0.04
            if '\n' in prev:
                return -0.12 * scale
        if glued_quote or end in QUOTES:
            if any(c in text[-80:] for c in '{}='):
                return -0.2 * scale
            if s.startswith(' ') and not glued_quote:
                return -0.2 * scale
            context = text.rstrip().rstrip('"“‘` ').rstrip()
            named_possessive = bool(re.search(r"[A-Z][^ ]*['’]s$", context))
            if named_possessive or re.search(r'\bauthor of$', context.lower()):
                return -6.0 * scale
            return (-4.8 if nearby else -2.7) * scale
        if end in {'(', '[', '*'}:
            return -1.0 * scale
        if kind:
            return (-7.8 if kind == 2 else -3.5) * scale
        if possessive:
            return -7.0 * scale
        if last in {'in', 'on', 'at'}:
            return -3.1 * scale
        if last in {'of', 'from', 'for', 'by', 'to', 'with', 'and', 'as'}:
            return (-4.5 if nearby else -2.4) * scale
        if end == ',':
            return (-3.4 if nearby else -2.1) * scale
        if p.islower():
            return (-3.4 if nearby else -1.3) * scale
        return -0.2 * scale
    if t in {'《', '「', '『', '〈'}:
        if t == '《':
            return -2.7 if kind else -1.15
        if t == '『':
            return -6.0 if kind else -2.4
        return -1.4 if kind else -0.35
    if t in QUOTES or glued_quote:
        opening = (glued_quote or s.startswith(' ') or prev.isspace()
                   or end in ':=([' or t in {'“', '‘', '«', '„'})
        if not opening:
            return 0.0
        if re.search(r'["”’][,;:]?$', text.rstrip()):
            return 0.03
        if any(c in text[-80:] for c in '{}='):
            return 0.0
        if author_of:
            return -5.0
        if kind:
            return -4.5 if kind == 2 or foreign_work else -1.5
        if possessive:
            if owner.lower() in {'it', 'that', 'there', 'he', 'she', 'what'}:
                return 0.0
            return -4.5 if named_owner else -2.6
        if set(wordnet.base_forms(last)) & SPEECH:
            return 0.10
        if nearby:
            return -0.3
        if sentence:
            return -0.5
        return -0.65 if t in {'«', '„'} else -0.15
    if t in {'A', 'An'}:
        if foreign_work:
            return -5.0
        return -1.0 if kind else -0.05
    if t == 'THE':
        return -0.18
    if t[:1].isupper() and kind and not sentence and '\n' not in prev:
        if p.islower():
            return -1.5 if kind == 2 else -0.6
        return 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    text, prev = ('', '') if start else carry[1:]
    s = prefix.token_strings[-1]
    value = predict(s, prev, text, start)
    return (doc, (text + s)[-160:], s), value

"""Negative pulses for short 'el' spelling fragments.

Look within a token, across e|l, and at short continuations of an el-ending
piece. Size, vowels, doubled l, and preceding m/n adjust the pulse. Spanish
versus English word frequencies weaken article-like el. Transliterate other
alphabets, but not Han/Hangul: their readings would invent Latin spellings.
This approximates the spelling response, not its detailed lexical variation.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()
VOWELS = frozenset('aeiou')

@lru_cache(maxsize=32768)
def spelling(token):
    if regex.search(r'[\p{Script=Han}\p{Script=Hangul}]', token):
        return ''
    return anyascii(token).lower().strip()

@lru_cache(maxsize=8192)
def spanish_bias(word):
    return zipf_frequency(word, 'es') - zipf_frequency(word, 'en')

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = spelling(token)
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    joined = (not token[:1].isspace() and s.isalpha()
              and previous.isalpha())
    p = previous if joined else ''
    n = len(s)

    if p.endswith('e') and s.startswith('l'):
        if n > 3:
            value = -0.53
        else:
            value = -1.56 if spanish_bias(previous) < -1 else -2.52
    elif s.startswith('el'):
        if s.count('e') > 1:
            value = -0.19
        elif p.endswith(('m', 'n')):
            value = -1.85
        elif 'll' in s:
            value = -0.33
        elif spanish_bias(previous) >= 2:
            value = -0.13
        else:
            value = -1.81 if s[-1:] in VOWELS else -0.94
    elif p.endswith('el'):
        if n > 2:
            value = -0.34
        elif len(p) > 2:
            value = -0.66
        else:
            value = -2.23 if s[:1] in VOWELS else -0.91
    elif 'el' in s:
        letters = sum(c.isalpha() for c in s)
        value = -0.57 if letters <= 3 else -0.095
    else:
        value = -0.002
    return (doc, s), value

"""Quantity and degree expressions, especially context-dependent English 'much'.

'Much' is positive after how/as/so, but usually negative after a copula.
The following 'as' also responds to the equality construction. Amount words
and the East Asian amount/extent characters are positive. There are also
spelling responses to MT/amt and short t/d fragments after a final m,
even inside unrelated words.
The partial UTF-8 prefix shared by 额 and nearby characters also responds.
An interpunct pair is negative; other tokens are left at zero.
"""
import regex as re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = re.findall(r"[A-Za-z]+", tail[-60:])
    previous = words[-1].lower() if words else ''
    value = 0.0

    if word == 'much':
        if previous == 'how':
            value = 6.3
        elif previous == 'as':
            value = 3.5
        elif re.fullmatch(r'so+', previous):
            value = 2.0
        elif previous == 'too':
            value = 0.65
        elif previous == 'very':
            value = 0.35
        elif previous == 'pretty':
            value = 0.0
        elif previous in {'this', 'that'}:
            value = 1.0
        elif previous == 'is':
