"""Component layers.1.mlp.down_proj:5027 is an "amount" detector.

It fires on the quantity sense of "much", on the word "amount" and its
abbreviations and translations, and is near zero elsewhere:

- "how much" (asking for an amount): about +6.5. "How much" is the same.
- "as much as": "much" about +3.5, the second "as" about +4.
- "so much": about +2. "too much" and "very much": about 0.
- "much" as a degree adverb ("is much better", "are much larger", "not much"):
  about -2.5, the opposite sign.
- "amount", "amounts", "Amount": about +2.
- the abbreviation "Amt" (token "amt", "Amt" or "mt" after "A"): about +5.
- Chinese and Japanese amount words: 額 about +10; 额, 金额, 总额, 限额, 数额 about +6.
- the extent words 幅 and 大幅 (a range of change): about +4.

Everything else predicts 0. Its mean and spread are matched to the component's
activations on 8,192 training rows (variance explained about 0.39 on eval).
"""

READS = ()

CJK_AMOUNT = {"額": 10.0, "额": 6.0, "金额": 6.0, "金額": 6.0, "總額": 6.0, "总额": 6.0,
              "限额": 6.0, "数额": 6.0, "高额": 6.0, "超额": 6.0}
EXTENT = {"幅": 4.0, "大幅": 4.0}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    v = 0.0
    if tok == "much":
        if prev == "how":
            v = 6.5          # "how much" asks for an amount
        elif prev == "as":
            v = 3.5          # "as much as"
        elif prev == "so":
            v = 2.0
        elif prev in ("too", "very", "pretty"):
            v = 0.5
        else:
            v = -2.5         # degree "much": "much better", "is much larger"
    elif tok == "as" and prev == "much":
        v = 4.0              # the second "as" of "as much as"
    elif "amount" in tok and "paramount" not in tok:
        v = 2.0              # amount, amounts, Amount
    elif tok == "amt":
        v = 3.5              # "Amt" abbreviation
    elif tok == "mt":
        v = 2.5              # fragment of "Amt" / "Amtmann"
    elif tok in CJK_AMOUNT:
        v = CJK_AMOUNT[tok]
    elif tok in EXTENT:
        v = EXTENT[tok]
    return carry, float(v)

