"""Approximate a document-opening response, including initial token repetition.

Source-code declarations, headings and isolated lowercase letters get a large
response. Common English words and line endings get less. Leading spaces,
case and character script refine the estimate. After the opening run: zero.
These are broad classes, not a token-by-token model of the opening amplitude.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def opening_value(s):
    word = s.strip()
    if s.startswith('<|'):
        return 0.11 if s == '<|endoftext|>' else 2.05
    if not word:
        if '\n' in s:
            return -0.75
        if s == '\t':
            return -3.9
        return 3.0 if len(s) >= 3 or '\t' in s else 0.1
    if s == 'package':
        return 27.0
    if s in {'import', 'from', 'def', 'int'}:
        return 9.9
    if s in {'const', 'var', 'function', 'module', 'using'}:
        return 4.4
    if set(word) == {'#'}:
        return 11.7 if len(word) == 1 else 9.3 if len(word) == 2 else 2.6
    if word in {'//', '/*', '/**'}:
        return 5.5 if '\n' in s else 7.7
    if word.isdecimal():
        return 0.0 if set(word) == {'0'} else 3.9
    if '\ufffd' in word:
        return 5.1
    if word.isascii() and word.isalpha():
        spaced = s.startswith(' ')
        if word.lower() == 'the':
            return 2.5 if spaced else 0.1
        if not spaced and len(word) == 1 and word.islower():
            return 6.7
        frequency = zipf_frequency(word.lower(), 'en')
        if frequency >= 5.8:
            return 0.0
        if spaced:
            return 1.3
        if not word.islower() and frequency >= 5.2:
            return -0.5
        return 3.7 if word.islower() else 1.8
    if word.isalpha():
        if regex.search(r'\p{Script=Han}', word):
            return 1.5
        return 3.0
    if '\n' in s or word.startswith('.') or word == '-':
        return 0.0
    return 2.5


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        return (document, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (document, None, 0.0), 0.0

"""A mixture of assurance/consequence phrases and nasal--sibilant spellings.

Large positives include ensure / make sure, and short 'ns' or split 'n+s'
fragments. Signed phrase corrections cover instrumental means, negated
knowing, personal obligation, and consequences. The spelling approximation
uses letter position, fragment length, case, and ordinary word frequency,
not token identities. A colon completing a document-initial 'Title:' header
is a separate large response. Other small token-specific effects are omitted.
"""
import re
import regex
from anyascii import anyascii
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=65536)
def letters(token):
    text = token.strip().lstrip("_([{.")
    if (regex.fullmatch(r'\p{Alphabetic}+', text)
            and not regex.search(r'[\p{Han}\p{Hangul}]', text)):
        return anyascii(text)
    return ''


@lru_cache(maxsize=65536)
def common(word):
    return max(zipf_frequency(word, lang) for lang in
               ('en', 'de', 'fr', 'es', 'pt', 'it')) >= 3.5


def signal(token, previous, tail):
    w, b = token.strip().lower(), previous.strip().lower()
    boundary = (not previous or token[:1].isspace()
                or not previous[-1:].isalnum())
    if token == ':' and tail == 'Title':
        return 13.626
    if boundary:
        if w in ('ensure', 'ensures', 'ensured', 'ensuring', 'insure'):
            if token.strip() == 'Ensure':
                return 3.61
            return {'ensuring': 5.87, 'ensures': 5.78,
                    'ensured': 4.10}.get(w, 4.69)
        if w == 'sure' and b in ('make', 'made', 'making', 'makes'):
            return 3.95
        if w == 'means':
            if b == 'no':
                return -6.43 if tail.lower().endswith('by no') else -2.51
            if b == 'by' or tail.lower().endswith('by all'):
                return -3.35
            return 1.38 if b in ('that', 'this', 'which') else 0.41
        if w in ('mean', 'meant'):
            if b in ('would', 'could', 'will', 'might', 'must', 'can'):
                return 2.22
            if re.search(r"(?:not|n't|n’t)$", tail.lower()):
                return 0.72
            return 1.45 if w == 'meant' else 0.10
        if w == 'meaning':
            return 1.10 if previous.rstrip().endswith(',') else 0.0
        if w == 'know' and re.search(r"(?:not|n't|n’t|dont)$", tail.lower()):
            return -1.97
        if w == 'must' and b in (
                'i', 'we', 'you', 'he', 'she', 'they', 'one', 'there'):
            return -0.99
        if w == 'to' and b in ('lead', 'leads', 'led', 'leading'):
            return 1.09
        if w == 'in' and b in ('result', 'results', 'resulted', 'resulting'):
            return 1.29
        if w in ('absence', 'aim') and b == 'the':
            return -1.55
        if w in ('response', 'effect', 'contrast', 'spite', 'conclusion',
                 'view') and b == 'in':
            return -1.47
        if w == 'no' and b in ('with', 'for', 'by', 'in', 'under'):
            return {'with': -1.02, 'for': -0.58, 'by': -1.93,
                    'in': -1.34, 'under': -2.96}[b]
    if w in ("'s", '’s') and b in ('men', 'women'):
        return 2.67 if b == 'men' else 1.13
    return spelling(token, previous, tail, boundary)


def spelling(token, previous, tail, boundary):
    r, p = letters(token), letters(previous)
    lo, pl = r.lower(), p.lower()
    if not boundary and (p + r).lower() in (
            'ensure', 'ensures', 'ensured', 'ensuring'):
        return 7.0
    if not r or tail.endswith('\\n'):
        return 0.003
    if not ('ns' in lo or (not boundary and
            (pl.endswith('ns') or
             (pl.endswith('n') and lo.startswith(('s', 'z')))))):
        return 0.003

    # Initialisms keep the nasal-s spelling in a particularly short form.
    if lo == 'ns':
        if r.isupper():
            return 8.0 if p == 'E' and not boundary else 3.8
        return 3.0 if boundary or not p else 1.7
    if r.isupper() and 'NS' in r and len(r) <= 5:
        if r == 'ENS' and boundary:
            return 6.0
        return 2.5 if len(r) <= 3 else 0.36

    # Vowel-bearing fragments: an initial 'ens' is quite different from
    # an ordinary plural word ending in -ns, or an internal suffix.
    if re.search('[aeiou]', lo):
        if re.fullmatch('[aei]ns', lo):
            if not boundary:
                return 0.263
            return 0.532 if common(lo) else 4.456
        if boundary:
            return 0.019
        if lo.startswith('s'):
            return 2.332 if len(r) <= 2 else 0.524 if len(r) <= 4 else 0.062
        return 0.068

    # Consonant clusters and abbreviated ns spellings. Long preceding
    # fragments and separated words generally suppress the response.
    if not p:
        return 3.060
    if boundary:
        return 2.959 if 'ns' in lo and len(r) <= 3 else 0.040
    if len(p) > 4:
        return 0.204
    return 2.062 if lo.startswith('s') and not r.istitle() else 0.895


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = signal(token, previous, tail)
    return (doc, token, (tail + token)[-48:]), float(value)

