"""Fires on the word "ensure" (and make sure), with a few related word families.

What the component responds to, as measured on training text:
- The verb "ensure" and its forms (ensure, ensures, ensuring, ensured, insure): large positive,
  about +5 on each use ("... and ensuring timely payment", "will ensure that").
- "sure" right after "make", "making" or "made" ("make sure that"): about +4.5.
  "sure" after other words ("not sure", "I'm sure") stays near zero.
- "means" / "meant" in the sense "results in" ("this means that", "meant some"):
  mildly positive, about +1.5. "by means" and "by no means" are strongly negative.
- Short letter fragments that spell "NS" (NS, NSW, DNS, ANSI, ns, sw, sd): about +2.5.
- "know" after a negation ("don't know", "not know"), and "must" or "mean" after a
  pronoun ("I must", "we mean"): mildly negative.
- The colon right after a document's first word "Title" (the second token of a document)
  is very large, about +13.6.
Everything else predicts zero. The program does not model the many small, diffuse
activations, which hold about half of the component's variance.
"""

READS = ()

ENSURE_FORMS = {"ensure", "ensures", "ensuring", "ensured", "insure", "insures", "insuring"}
MAKE_WORDS = {"make", "makes", "making", "made"}
NS_FRAGMENTS = {"ns", "sns", "dns", "nsw", "nsa", "cns", "ansi", "ans", "sw", "sd"}
RESULT_VERBS = {"means", "meant"}
BY_OR_NO = {"by", "no"}
NEGATIONS = {"not", "t", "dont", "do", "never"}
PRONOUNS = {"i", "you", "we", "they", "he", "she"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    # carry = (document id, index of the current token within its document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        index = 0
    else:
        index = carry[1] + 1
    cur = word(prefix.token_strings[-1])
    prev = word(prefix.token_strings[-2]) if index > 0 else ""
    if cur in ENSURE_FORMS:
        value = 5.0
    elif cur == "sure" and prev in MAKE_WORDS:
        value = 4.5
    elif cur in RESULT_VERBS:
        value = -4.0 if prev in BY_OR_NO else 1.5
    elif cur in NS_FRAGMENTS:
        value = 2.5
    elif cur == "know" and prev in NEGATIONS:
        value = -2.2
    elif cur in ("must", "mean") and prev in PRONOUNS:
        value = -1.2
    elif cur == ":" and prev == "title" and index == 1:
        value = 13.6
    else:
        value = 0.0
    return (doc, index), value

