def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail, previous = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value, tail = predict(token, tail, previous, first)
    return (doc, tail, token), float(value)

programs.haiku:
"""Layer-1 MLP unit 5032 (down_proj): a "d-word" detector that goes negative.

Almost always near zero. It dips negative on the letter d in a few places:

1. The auxiliary "did" / "do" that opens a question, strongest after a wh-word:
   "How did" (-4.3), "Where did" (-4.3), "Why did" (-4.3), "How do" (-1.4), "Did you" (-2.6).
   "did" after "and" is -2.2; other "did" is about -0.9; other "do" is about 0.
2. Other short English d-words: ded, dod, dude, dad, dead, deed, daddy, dvd, died.
   Each has a typical strength, given in D_WORD_VALUE.
3. A short word piece that contains a d, continuing a word whose previous piece
   also had a d. If that previous piece ends in a capital D (or Cyrillic/Arabic d),
   the response is strong (-3): "D" + "ad", "Da" + "ed", "kaiteD" + "ID".
   If it ends in a lowercase d, the response is mild (-0.8): "epid" + "id".
4. A doubled middle dot filler "··": a steady -2.9.

Everything else is 0. The program is a readable rule set, not a table of ids.
What it leaves out: the many small, context-dependent wobbles (about 0.05-0.1)
on ordinary tokens, and the d-fragments that appear in code or URLs (no response).
"""

READS = ()

WH_WORDS = {"how", "where", "what", "why", "who", "when", "which"}
SENTENCE_STARTS = {"", ".", "?", "!", "\n", '"', "“"}
D_LETTERS = set("dDдДد")  # Latin d/D, Cyrillic д/Д, Arabic dal
D_WORD_VALUE = {
    "did": -0.9, "do": 0.0, "dad": -2.6, "dead": -1.8, "ded": -3.2, "dod": -5.0,
    "dude": -4.2, "deed": -2.0, "died": -0.3, "daddy": -2.5, "dvd": -1.8,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip().lower()
    prev_raw = ""
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev_raw = prefix.token_strings[-2]
        prev = prev_raw.strip().lower()

    if cur in ("did", "do"):
        if prev in WH_WORDS:
            value = -4.3 if cur == "did" else -1.4
        elif cur == "did" and prev == "and":
            value = -2.2
        elif cur == "did" and prev in SENTENCE_STARTS:
            value = -2.6
        else:
            value = D_WORD_VALUE[cur]
    elif cur in D_WORD_VALUE:
        value = D_WORD_VALUE[cur]
    elif raw == "··":
        value = -2.9
    elif not raw[:1].isspace() and len(cur) <= 4 and any(c in D_LETTERS for c in cur):
        if prev_raw[-1:] in ("D", "Д"):
            value = -3.0
        elif any(c in D_LETTERS for c in prev_raw):
            value = -0.8
        else:
            value = 0.0
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Sparse responses to 'brief/simple' Chinese words and split characters.

简/簡 and their compounds receive large negative values; a few graphic or
meaning neighbours receive smaller ones. For a split UTF-8 character, a
radical (Han) or initial consonant (Hangul) gives a coarse approximation.
A separate set of rules recognizes document-opening labels, comments,
markup, the number prefix 12, and leading carriage-return runs.
Unlisted cases are predicted as zero, not as a full account of the component.
"""
from functools import lru_cache
import unicodedata
import unihan
from opencc import OpenCC

READS = ()
_simplify = OpenCC('t2s').convert

# The 简 ('brief/simple') family; fused compounds have different strengths.
BRIEF_WORDS = {
    '简': -7.1,
    '简称': -8.5, '以下简称': -5.0,
    '简介': -3.8, '简直': -4.5, '简化': -2.3,
    '简单': -1.0, '简单的': -0.6,
}
RELATED = {
    '筒': -4.5, '箱': -0.4,  # bamboo-topped characters resembling 简
    '剪': -2.3, '繁': -1.8,
    '减': -0.8, '检': -0.6, '洗': -0.7, '洁': -0.6,
}
UNFINISHED_RADICAL = {
    'bamboo': -1.5, 'silk': -1.2, 'knife': -2.2, 'eye': -0.7,
}
UNFINISHED_ONSET = {'ᄇ': -2.0, 'ᄎ': -1.1, 'ᄑ': 0.8}


@lru_cache(maxsize=16384)
def lexical(text):
    word = _simplify(text.strip())
    return BRIEF_WORDS.get(word, RELATED.get(word, 0.0))


@lru_cache(maxsize=2048)
def unfinished(fragment):
    # The first compatible codepoint estimates this unfinished UTF-8 band's
    # radical or Korean initial consonant, without knowing the final byte.
    if len(fragment) != 2 or not 0xE0 <= fragment[0] < 0xF0:
        return 0.0
    char = (fragment + b'\x80').decode('utf-8', 'ignore')
    if not char:
        return 0.0
    radical = unihan.radical(char)
    if radical:
        return UNFINISHED_RADICAL.get(unihan.radical_name(radical), 0.0)
    if 'HANGUL SYLLABLE' in unicodedata.name(char, ''):
        onset = unicodedata.normalize('NFD', char)[0]
        return UNFINISHED_ONSET.get(onset, 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', b'', True)
    _, position, previous, tail, only_cr = carry
    b = prefix.token_bytes[-1]
    joined = tail + b
    value = lexical(prefix.token_strings[-1])

    if len(b) == 1 and 0x80 <= b[0] < 0xC0:
        # A newly added continuation byte may complete a character, or leave
        # just its last byte missing. Find its most recent UTF-8 lead byte.
        start = next((i for i in range(len(joined)-1, -1, -1)
                      if joined[i] >= 0xC0), None)
        if start is not None:
            fragment = joined[start:]
            value = unfinished(fragment)
            if len(fragment) == 3:
                value = lexical(fragment.decode('utf-8', 'ignore'))
        if joined.endswith(' 简'.encode()[:-1]):
            value = -7.0

    # These are opening formats, not all occurrences of their punctuation.
    if position == 0:
        if b == b'//\n':
            value = -10.5
        elif b == b'<!':
            value = -4.8
    if position == 1:
        if previous == b'Title' and b == b':':
            value = -10.83
        elif previous == b'Posted' and b == b' on':
            value = -5.05
        elif previous == b'1' and b == b'2':
            value = -5.18
    if only_cr and b == b'\r':
        value = -5.2
    only_cr = only_cr and b == b'\r'
    return (doc, position + 1, b, joined[-4:], only_cr), value

"""A small collection of local text cues, mostly source-code boilerplate.

Positive pulses mark patch paths, standard-library names, and a few familiar
code/header constructions. Dotted mathematical contents pages also have a
pulse on italic phi; two Chinese benefit/grant compounds pulse on their final
character. Initial-token estimates use length and case, with exceptions for
digits, special tokens, and SQL-comment starts. Initial 'Title:' metadata and
repeated middle dots are negative cues. Everything else is near zero. This is
a partial predictor, not a general code parser.
"""
import re

READS = ()

# Suffixes of C# standard-library namespace imports.
NAMESPACES = {
    'Threading.Tasks': 1.9,
    'Text': 0.8,
    'IO': 1.0,
    'Data': 1.4,
    'Drawing': 0.7,
    'Collections.Generic': -0.25,
    'Net': 0.65,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = b'' if first else carry[1]
    tail = (old + prefix.token_bytes[-1])[-640:]
    # Keep byte fragments until their Unicode character is complete. Treat
    # escaped newlines in quoted source code like ordinary newlines.
    text = tail.decode('utf-8', errors='replace')
    text = text.replace('\\n', '\n').replace('\\r', '\r')
    source_header = False if first else carry[2]
    source_header |= len(tail) < 640 and text.startswith('using System')
    value = -0.001
    if first:
        word = text.strip()
        value = -0.04 - 0.04 * min(len(word), 4)
        if word.istitle():
            value -= 0.1
        elif word.islower() or word.isupper():
            value += 0.08
        if word.isdigit() or text.startswith('<|'):
            value = 0.02
        if text == '--':
            value = 1.07

    if text == 'Title:':
        value = -3.79
    elif text.endswith('····'):
        value = -1.22
    elif text.endswith('\n+++ b') or text == '+++ b':
        value = 0.85
    elif text.endswith('mkdir -p'):
        value = 0.8 if ('&&' in text or text.count('mkdir') > 1) else 0.2
    elif re.search(r'import re\r?\nimport sys\Z', text):
        value = 1.1
    elif re.search(r'\bsys\.path\Z', text):
        value = 2.1
    elif 'using System.' in text:
        namespace = re.search(r'using System\.([A-Za-z.]+)\Z', text)
        if namespace:
            name = namespace[1]
            value = NAMESPACES.get(name, value)
            if name == 'Threading.Tasks':
                value = 1.9 if source_header else 0.8
            elif name == 'Text' and not source_header:
                value = 0.5
    if text.endswith('UnityEngine.UIElements'):
        value = 1.7
    elif text.endswith('ssize_t'):
        value = 1.1
    elif text.endswith('OR exit'):
        value = -1.0
    elif re.search(r'\bDefinition for\Z', text):
        value = 3.2 if '# Definition for' in text else 1.5
    elif text.endswith(('"__esModule', "'__esModule")):
        value = 2.4
    elif text.endswith('@OLD_CHARACTER_SET_RESULTS'):
        value = 0.8
    elif text.endswith(('补助金', '失业金')):
        # The final character of subsidy/unemployment-benefit compounds.
        value = 2.2
    elif text.endswith('Syntax hints'):
        value = 1.4
    elif (text.endswith('/*  ') and '\n' in text and
          ':::' in text.split('\n')[-2]):
        # The filename line of a decorative C source-file header.
        value = 1.65
    elif (' . . . ' in text and
          re.search(r'\d+ \(+𝜑\Z', text)):
        value = 1.4
    elif text.endswith('System.in'):
        value = 0.65
    elif text.endswith('typedef int'):
        value = 1.0
    elif text.endswith('\n RUN'):
        value = 0.75
    return (doc, tail, source_header), value

"""Predict closing delimiters of named markup, rather than arithmetic brackets.

Opening XML/HTML tags, C/C++ includes, LaTeX environment declarations and
bracketed labels give positive pulses. End tags and ordinary indexing are
weaker. Delimiters merged with prose or code punctuation usually do not
fire. Leading labels get a larger pulse. A small document-initial baseline
also depends on capitalization and spacing. The state is just a text tail
and a position counter, both reset at document boundaries.
"""
import re

READS = ()
VOID_TAGS = {'br', 'hr', 'img', 'input', 'meta', 'link'}
INLINE_TAGS = {'a', 'span', 'strong', 'em', 'i', 'code', 'p'}
CONTAINERS = {'script', 'style', 'html', 'head', 'body', 'summary'}
TRACEBACK_NAMES = {'module', 'dictcomp', 'listcomp', 'genexpr', 'lambda'}


def closing_value(token, before):
    s = token.lstrip(' \t')
    if re.fullmatch(r'''[\\"']*>(?:\s*|</?|["'])''', s):
        left = before.rfind('<')
        if left < 0:
            return 0.0
        body = before[left + 1:]
        if '>' in body:
            return 0.0
        if re.search(r'#\s*include\s*$', before[:left]):
            return 2.1 if body.endswith('.h') else 3.6
        if body.startswith('/'):
            return 0.45 if '\n' in s else 0.08
        boundary = left == 0 or (
            not before[left - 1].isalnum() and before[left - 1] not in ':_'
        )
        tag = re.match(r'[A-Za-z_][\w:.-]*', body)
        if boundary and tag:
            name = tag.group()
            if name in {'nil', 'NULL', 'EMAIL', 'NAME', 'URL', 'PHONE'}:
                return 0.1
            if name.startswith('PRESIDIO_'):
                return 0.0
            if len(name) > 1 or name.islower():
                if len(body) > len(name):
                    if name in {'script', 'style'}:
                        return 4.0 if '\n' in s else 1.5
                    return 1.5 if '\n' in s else 0.7
                if name in TRACEBACK_NAMES:
                    return 0.8
                if name in VOID_TAGS:
                    return 0.2
                if name in INLINE_TAGS:
                    return 1.4 if s.endswith('<') else 0.45
                if name in CONTAINERS:
                    return 4.8 if '\n' in s else 2.8
                if name in {'td', 'th', 'li'}:
                    return 2.0 if '\n' in s else 1.2
                return 4.0 if '\n' in s else 1.6
        return 0.65 if '@' in body or '_at_' in body else 0.0

    if s.startswith('}'):
        m = re.search(r'(?<![a-z])(begin|end|label)\{[\w*.-]+$', before)
        if m:
            if s.startswith('}{'):
                return 0.35
            if s.startswith('}&'):
                return 0.8
            if m[1] == 'begin':
                if s == '}\\':
                    return 8.5
                return 4.3 if '\n' in s else 5.8
            if m[1] == 'label':
                return 1.1
            return 0.7 if s == '}\n' else 0.3 if s == '}' else 0.1
        if re.search(r'begin\{array\}\{[lcr| ]+$', before):
            return 4.5

    if re.fullmatch(r'''\](?:[ \t]*|\r?\n|\\|['"])''', s):
        if re.search(r'begin\{[\w*]+\}\[[^\]]+$', before):
            return 3.0
        if s == ']\\' and re.search(r'\[@[^\]]+$', before):
            return 1.0
        left = before.rfind('[')
        if left >= 0:
            body = before[left + 1:]
            if '\n' not in body and ']' not in body:
                if left > 0 and before[left - 1] == '#':
                    return 2.2 if '\n' in s else 1.2
                boundary = left == 0 or not before[left - 1].isalnum()
                if boundary and body and body[-1].isalpha():
                    return 0.5
                if boundary and body.startswith('Command finished'):
                    return 0.2
                if boundary and body.startswith('Current working directory'):
                    return 0.35

    if s == '＞' and '＜' in before:
        return 2.0
    if s == '】' and '【' in before:
        return 0.4
    if s == '》' and '《' in before:
        return 0.17
    return 0.0


def predict(token, before, position):
    value = closing_value(token, before)
    if value > 0 and position < 16 and token.startswith(']'):
        value *= 2.0
    if token == '】' and before.startswith('【') and position < 8:
        value = 2.5
    if position == 0 and not value:
        if token.isdigit():
            return 0.1
        if token.startswith('<|'):
            return -0.45
        if token[:1].isupper():
            return -0.4
        return -0.08 if token.startswith(' ') else -0.2
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, position)
    return (doc, (before + token)[-512:], position + 1), value

"""A document-initial pulse, often strongest on short capitalized tokens.

The pulse stops when a different token arrives. Its size is approximated from
case, length, script, English word frequency and word endings.
These rules leave most of the token-specific variation unexplained.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def initial_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return 0.5
    if not word:
        return 0.0
    if word.isdecimal():
        return -0.4
    if not any(c.isalpha() for c in word):
        return -0.2
    if regex.search(r'\p{Script=Arabic}', word):
        return 5.0
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 3.5
    if not regex.search(r'\p{Script=Latin}', word):
        return 0.4
    frequency = zipf_frequency(word, 'en')
    # The English definite article has distinct sentence-initial forms.
    if word.lower() == 'the':
        if word == 'The':
            return 2.6 if text.startswith(' ') else 4.6
        return 0.4
    # Lowercase fragments ending in the liquid letters l/r are stronger.
    if word.islower() and word.endswith(('l', 'r')):
        return 3.7 if frequency < 4.6 else 1.5
    if len(word) == 1:
        return 1.1 if word.islower() else 0.9
    if word.istitle():
        if len(word) <= 3:
            return 5.1 if frequency < 4.25 else 2.3
        return 2.6
    if word.isupper():
        return 3.4
    return 0.45 if frequency >= 5.5 else 1.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        carry = (doc, token, True, value)
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False, carry[3])
    return carry, carry[3] if carry[2] else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:5038: a "first token of a document" detector.

What it does: the component is silent everywhere except on the first token of each
document (the token right after a document break, or the first token of a row). There
it writes a strong value, typically 1 to 3 for ordinary text, whose size depends on which
token it is. The program predicts that value from simple kinds of token:
  - base level 1.2 at a document start, 0 at every other position;
  - +1.5 if the token starts with a capital letter (names, title-case word starts);
  - -1.5 if it contains a digit;
  - -2.2 if it contains CJK characters (Han, kana, hangul);
  - +1.7 for other non-ASCII text (Cyrillic, Arabic, accented Latin, ...);
  - -1.3 if it is punctuation only.

Why: at a document start, attention can see only the token itself, so the component
responds to the token's identity. Its size is a fairly idiosyncratic function of that
identity; these word-class features capture only part of it (about 0.3 of the variance on
eval). A per-token table of the document-start values would explain about 0.9, but it
would be a list of arbitrary token ids, so it is not used here.
"""

READS = ()

BASE = 1.2


def step(carry, prefix, upstream):
    t = prefix.position
    if t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0  # inside a document: silent
    s = prefix.token_strings[-1]
    value = BASE
    if s.strip()[:1].isupper():
        value += 1.5
    if any(c.isdigit() for c in s):
        value -= 1.5
    if any("぀" <= c <= "ヿ" or "㐀" <= c <= "鿿" or "가" <= c <= "힯" for c in s):
        value -= 2.2
    elif any(ord(c) > 127 for c in s):
        value += 1.7
    if s.strip() and all(not c.isalnum() for c in s.strip()):
        value -= 1.3
    return None, value

programs.sol:
"""A sparse detector of C-style control-statement heads.

Predict a positive pulse on if/for/while/foreach/switch when earlier
punctuation suggests semicolon-and-brace code, especially at the start
of an indented line. Tabs and recent semicolons provide weaker evidence.
Else-if is another recognizable statement head. Predict zero elsewhere;
this does not explain the component's diffuse background or unusual
first-token responses. Keep only a short suffix, resetting each document.
"""
READS = ()
CONTROL_HEADS = {'if', 'for', 'while', 'foreach', 'switch'}


def control_value(word, before, previous):
    if word not in CONTROL_HEADS or not before:
        return 0.0
    text = before.replace('\\n', '\n').replace('\\t', '\t')[-400:]
    semicolons = text.count(';')
    braces = '{' in text or '}' in text
    line = text.rsplit('\n', 1)[-1].strip()
    line_start = not line or line.isdigit()  # allow source line numbers
    end = text.rstrip()

    if word == 'if' and end.split()[-1:] == ['else']:
        return 0.53
    if end.endswith((';', '{', '}')):
        if not line_start:
            return 0.27
        if not semicolons:
            return 0.44
        return 0.87 if previous.isspace() else 0.71
    if '\t' in previous:
        return 0.67 if semicolons else (0.34 if braces else 0.0)
    if semicolons >= 3:
        if previous.isspace():
            return 0.77
        return 0.33 if word == 'if' else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    value = control_value(token.strip(), before, previous)
    return (doc, (before + token)[-600:], token), value

programs.haiku:
"""Statement-opening control keyword in source code.

Layer-1 MLP unit 5039 (down_proj) is a control-flow detector. It fires on the keyword
that opens a conditional or loop in source code -- `if`, `for`, `while`, `foreach`,
`switch` -- when that keyword is the first word of a statement: first on its line after
indentation, or right after a `{`, `}` or `;`. Those tokens get a value of about 0.5
(the component's typical response there). Every other token gets 0. Mid-line uses such
as `x if y` are left at 0 because they are not reliably positive.
"""

READS = ()

KEYWORDS = {"if", "for", "while", "foreach", "switch"}
CLOSERS = {"{", "}", ";"}
STATEMENT_VALUE = 0.5


def step(carry, prefix, upstream):
    # carry: (at_line_start, last non-blank character) before this token
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    at_start, last = (True, "\n") if (new_doc or carry is None) else carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token.strip() in KEYWORDS and (at_start or last in CLOSERS):
        value = STATEMENT_VALUE
    for ch in token:
        if ch == "\n":
            at_start, last = True, "\n"
        elif ch in " \t\r":
            pass
        elif ch.isdigit() and at_start:
            pass  # line-number gutter in a listing
        else:
            at_start, last = False, ch
    return (at_start, last), value

programs.sol:
"""Recognize proof-related words, their complements, and a few spelling effects.

The main negative signal is prove and its inflections, including a word split
between tokens.  Improve is not a trigger; approve is much weaker.  Auxiliary
verbs adjust the strength.  Demonstrative uses of show and following 'that'
receive smaller negative predictions.  Positive spelling effects include
split Sten-, Sven-, Steve-, stave-, and repeated middle-dot punctuation.
Only an unfinished word and the previous token are remembered.
"""
import re

READS = ()
PROOF_FORMS = {"prove", "proved", "proven", "proves", "proving"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, last_proof = "", "", 0.0
    else:
        _, previous, word, last_proof = carry
    raw = prefix.token_strings[-1]
    token = raw.strip()
    text = token.lower()
    prev = previous.lower()
    before = word if raw and raw[0].isalpha() else ""
    joined = before + text
    tail = re.search(r"[a-z]+$", joined)
    word = tail.group()[-32:] if tail else ""
    value = 0.0
    proof = 0.0

    if text in PROOF_FORMS and before in {"", "dis"}:
        proof = -6.6 if text in {"proved", "proving"} else -7.1
        if prev in {"we", "is", "was", "can"}:
            proof = -4.8
        elif prev in {"has", "have", "'s"}:
            proof = -9.0
        elif prev == "to":
            proof = -7.7
    elif before in {"pro", "dispro"} and text.startswith("v"):
        proof = -3.0
        if text in {"ve", "ved", "ven", "ves", "ving", "vable", "vably"}:
            proof = -8.0
