"""Approximate pulses on noun-phrase markers, command arguments and starts.

Most tokens get nearly zero. Articles, possessives and contracted articles
in several European languages get positive pulses, with recent word-frequency
evidence disambiguating shared spellings. Capitalized forms are weaker.
Command arguments, option names and documentation delimiters also get pulses.
At a document start, a small WordNet word-class rule replaces these rules;
control markers instead get a small negative baseline.
It captures only broad tendencies, not the large word-specific start effects.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()

# Definite articles, possessives, and preposition+article contractions.
# Each group gives one approximate pulse size to a grammatical paradigm.
GRAMMAR = {
    'fr': (
        (.7, 'le la l mon ma mes notre nos votre vos ses son sa'),
        (.4, 'les'), (.7, 'des'), (1.2, 'du au aux'),
    ),
    'it': (
        (.8, 'il lo la i l suo nostro'), (.5, 'gli le'),
        (1.3, 'del dello della dell al allo alla all dal nel'),
        (.9, 'ai agli dalla dalle nella nelle nell'),
        (.7, 'dei degli delle alle'),
    ),
    'es': (
        (.7, 'el la su sus nuestro nuestra'),
        (.4, 'los las'), (1.5, 'del'), (1., 'al'),
    ),
    'pt': (
        (.85, 'o a os as seu sua meu minha nosso nossa'),
        (1.2, 'do da'), (1., 'dos das no na nos nas ao aos'),
        (1.1, 'à às'), (1., 'pelo pela pelos pelas'),
    ),
    'de': (
        (.25, 'der die eine einer'), (.1, 'ein'),
        (.8, 'das den eines'), (.6, 'dem einem'), (1.2, 'des'),
        (1.4, 'im am beim zum vom ins'), (1., 'zur'),
        (.7, 'mein meine meiner ihren ihrem unser'),
    ),
}
MARKERS = {
    lang: {word: size for size, words in groups for word in words.split()}
    for lang, groups in GRAMMAR.items()
}
LANGUAGES = ('fr', 'it', 'es', 'pt', 'de', 'ro', 'tr', 'pl')


@lru_cache(maxsize=40000)
def language_evidence(word):
    english = zipf_frequency(word, 'en')
    return tuple(max(-2., min(2., zipf_frequency(word, lang) - english))
                 for lang in LANGUAGES)


DEFAULT = {
    word: sum(table[word] for table in MARKERS.values() if word in table)
    / sum(word in table for table in MARKERS.values())
    for table in MARKERS.values() for word in table
}
AMBIGUOUS = set('a o as do no nos i am l ma mon mein all'.split())
COMMANDS = set(
    'git npm pip pip3 cargo apt conda yarn docker cmake net xargs'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        scores = [0.] * len(LANGUAGES)
        tail = ''
        pending = ''
    else:
        _, scores, tail, pending = carry
    word = token.strip().lower()
    # Update language evidence only when a complete word has arrived.
    pieces = re.findall(r"[^\W\d_]+|[\W\d_]+", pending + token.lower())
    pending = ''
    for j, piece in enumerate(pieces):
        if piece.isalpha():
            if j == len(pieces) - 1:
                pending = piece
            else:
                evidence = language_evidence(piece)
                scores = [.92 * v + e for v, e in zip(scores, evidence)]
    local_scores = scores
    if word in DEFAULT:
        local_scores = [s + 2 * e for s, e in
                        zip(scores, language_evidence(word))]
    best = max(range(len(scores)), key=local_scores.__getitem__)
    lang = LANGUAGES[best] if local_scores[best] > 2.0 else 'en'
    value = -.005
    boundary = token[:1].isspace() or not tail[-1:].isalpha()
    if word in DEFAULT and boundary:
        if lang != 'en':
            value = MARKERS.get(lang, {}).get(word, 0.0)
        elif word not in AMBIGUOUS:
            value = DEFAULT[word] * .7
    if token.strip()[:1].isupper() and lang != 'de':
        value *= .5
    # Russian possessive inflections and Swedish 'our'.
    if boundary and re.fullmatch(
            r'(?:наш|ваш)'
            r'(?:а|е|и|его|ей|ему|им|их|ими|ем|у)?'
            r'|(?:сво|тво|мо)'
            r'(?:й|я|ё|и|ю|его|ей|ему|им|их|ими|ём|ем)'
            r'|vår(?:t|a)?', word):
        value = .65
    # Option letters and command verbs are a second, syntactic source of pulses.
    if (token == token.strip() and token.isascii() and token.isalpha()
            and re.search(r'\s--?$', tail)):
        value = 1.0
    previous = re.search(r'([A-Za-z0-9]+)$', tail.rstrip(' \t'))
    command = previous.group(1) if previous else ''
    go_action = command == 'go' and word in {
        'run', 'test', 'build', 'install', 'get', 'mod', 'generate', 'fmt', 'vet'
    }
    if word.isalpha() and boundary and (command in COMMANDS or go_action):
        value = 1.2
    if word in ('param', 'returns') and tail.endswith('@'):
        value = .85
    if token == '{' and re.search(r'\\(?:begin|end)$', tail):
        value = .8
    value *= .75
    if first:
        parts = wordnet.parts_of_speech(word)
        senses = wordnet.categories(word)
        value = (.5 + .3 * ('noun' in parts) + .55 * ('verb' in parts)
                 - .2 * ('adjective' in parts) - .7 * ('adverb' in parts)
                 + .85 * ('noun.time' in senses)
                 + .7 * ('noun.location' in senses))
        if token.startswith('<|') and token.endswith('|>'):
            value = -.25
    return (doc, scores, (tail + token)[-100:], pending), value

programs.haiku:
"""Candidate D: non-English articles and contractions; a document's first token gets a
token-specific value (sign by surface type); no dot-leader rule."""
READS = ()
CONTRACTED = {" del", " della", " dell", " dal", " dalla", " nel", " nella", " sul", " sulla",
              " vom", " zum", " zur", " beim", " im", " au", " alla", " du"}
ARTICLES = {" la", " le", " el", " il", " lo", " gli", " das", " den", " dem", " des", " der",
            " die", " dei", " het", " da", " los", " aux", " ses", " suo", " sua", " votre",
            " ihre", " seine", " al", " o", " os", " dos"}

def start_value(s):
    t = s.strip()
    if any(c in s for c in '\\"\'`'):
        return -1.1
    if s.startswith(" ") and t.isascii() and t.isalpha() and t.islower():
        return 1.0
    if t.isascii() and t.isalpha() and t[:1].isupper():
        return 0.5
    return 0.6

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return None, float(start_value(tok))
    if tok in CONTRACTED:
        value = 1.2
    elif tok in ARTICLES:
        value = 0.5
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A sparse, context-sensitive separator predictor.

Strong positives mark tabs between fields, path slashes, LaTeX argument
braces, abbreviation punctuation, and unusual spaces. Smaller rules cover
angle-bracket syntax and calendar months. A document-initial 'Title:' label
has an exceptionally large response; a document-initial tab is negative.
Other tokens receive zero. This does not explain all lexical fluctuations.
"""
import re

READS = ()


def separator_value(s, b, previous, tail, initial, previous_bytes):
    if s == ':' and tail == 'Title':
        return 18.144
    if s == '月' and re.search(r'[0-9零〇一二三四五六七八九十廿]$', tail):
        return 0.95
    if s == '\u2009' or (b == b'\x89' and previous_bytes.endswith(b'\xe2\x80')):
        return 1.6  # Thin space, possibly split across byte-level tokens.
    if s in ('\b', '\f', '\v'):
        return 0.35

    if s == '\t':
        if initial:
            return -5.197
        if previous.isdigit():
            return 1.38
        if previous and set(previous) == {'\t'}:
            return 1.48
        if previous.endswith('\n'):
            return 0.13
        return 1.26
    if s and set(s) <= {'\t', '\n'} and '\t' in s:
        if '\n' in s:
            return 0.58 if s == '\t\n' and previous.isdigit() else 0.23
        return 0.41 if previous.isdigit() else -0.05

    if s == '\xa0':
        if previous == ' ':
            return 0.8
        if previous.rstrip().endswith('–'):
            return -0.22
        return 1.07 if previous.endswith('\xa0') else 0.34
    if s in ('.', '.,'):
        if re.search(r'\bi\.e$', tail, re.I):
            return 1.16
        if re.search(r'\be\.g$', tail, re.I):
            return 1.46

    if s == '{':
        command = re.search(r'\\([a-zA-Z]+)$', tail)
        if command:
            # Typography, environments, references, roots and fractions.
            return {
                'mathrm': 1.52,
                'begin': 1.42,
                'ref': 0.22,
                'sqrt': 0.59,
                'frac': 1.21,
            }.get(command[1], 0.93)
    if s == '/':
        word = re.split(r'\s', tail)[-1]
        if '/' in word:
            return 1.34
        end = re.search(r'[\w.-]+$', tail)
        if end and len(end[0]) > 2 and not end[0].isdigit():
            return 0.5
        return 0.08
    if s.strip() in ("'/", '"/'):
        return 0.37
    if s == '>' and re.search(r'<[a-zA-Z][\w:-]*$', tail):
        return 0.44
    if s == '<' and re.search(r'[A-Z][\w]+$', tail):
        return 0.85
    if s == ':' and re.search(r'\.[a-zA-Z]{1,6}$', tail):
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous, tail, previous_bytes = ('', '', b'') if initial else carry[1:]
    s, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = separator_value(s, b, previous, tail, initial, previous_bytes)
    return (doc, s, (tail + s)[-180:], b), value

"""Approximate three surface responses: first-person words, comment/heading
markers, and blank lines. Comment markers get larger values in source-like
contexts. 'I' gets larger values after clause boundaries and smaller ones in
some non-pronoun contexts. Blank-line tokens get a boost when the last completed
line was nonempty, with separate rules for thinking tags and attached spaces.
Everything else is near zero. State resets at document boundaries.
"""
import re

READS = ()
CONNECTIVES = set('''and but or so if when while because since although though
as where what which than then however perhaps maybe now well yet until unless
once whether therefore otherwise'''.split())
PREPOSITIONS = set('''of in on at to from for by with without into onto upon
under over through between among during before after about per via
 de del della di da du des van von'''.split())
DETERMINERS = set('the a an this these those my your his her its our their'.split())
CODE_PUNCTUATION = set('=;{}[]_`')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '', 0)
    _, recent, line, previous_line, previous_token, age = carry
    s = prefix.token_strings[-1]
    q = s.strip()
    p = previous_token.strip()
    value = -0.002

    if q in ('I', 'i', 'Im', 'We', 'we'):
        if q == 'I':
            if s.startswith(' '):
                if p.lower() in CONNECTIVES:
                    value = 0.80
                elif p.endswith(','):
                    value = 0.82
                elif p.lower() in PREPOSITIONS | DETERMINERS:
                    value = 0.12
                else:
                    value = 0.58
            else:
                value = 0.55 if '\n' in previous_token else 0.33
                if p.isalpha():
                    value = 0.0
        elif q == 'i':
            value = 0.13 if s.startswith(' ') else 0.02
        else:
            value = 0.35 if q == 'Im' else (0.10 if q == 'We' else 0.06)

    elif ('\n' not in s and q
          and (set(q) <= set('/#') or q in ('--', '/*', '%', '*'))):
        logical_line = re.split(r'\n|\\n', recent)[-1]
        indent = len(logical_line) - len(logical_line.lstrip())
        line_start = not logical_line.strip()
        code = sum(c in CODE_PUNCTUATION for c in recent[-100:])
        if q == '--':
            value = 1.18 if line_start else 0.0
        elif q == '/*':
            value = 0.68
        elif q == '%':
            value = 0.35 if line_start else 0.0
        elif q == '*':
            value = 0.18 if line_start and s.startswith(' ') else 0.0
        elif q.startswith('//'):
            if len(q) > 2:
                value = 1.0 if len(q) == 3 else 0.0
            elif not line:
                value = 1.0
            elif sum(c in CODE_PUNCTUATION for c in line) > 4:
                value = 1.99
            else:
                value = 1.64
                if previous_line.lstrip().startswith('//'):
                    value -= 0.25
        elif q.startswith('#'):
            if len(q) > 1:
                value = 0.65 if len(q) == 2 else (0.23 if len(q) == 3 else 0.08)
            elif indent > 2:
                value = 1.53 if line_start else 1.01
            elif not code:
                value = 0.44 if line_start else 0.11
            elif line_start:
                value = 1.22
            else:
                value = 0.74 if s.startswith(' ') else 0.22
            if recent.rfind('\\n') > recent.rfind('\n'):
                value += 0.45

    elif '\n\n' in s:
        if s.startswith(' \n'):
            value = -0.074
        elif previous_line:
            if not q:
                value = 1.30 if p == '<think>' else 0.97
            else:
                value = 0.60 if len(line) <= 170 else 0.30
        elif p == '</think>':
            value = 0.70
        elif s.startswith(','):
            value = -0.134
        else:
            value = 0.043

    if s == '\n':
        value = -0.02
    if age == 0 and value == -0.002:
        value = -0.10
    if '\n' in s:
        lines = (line + s).split('\n')
        previous_line, line = lines[-2:]
    else:
        line = (line + s)[-500:]
    state = (doc, (recent + s)[-500:], line, previous_line, s, age + 1)
    return state, value

