"""Draft 6: comment and heading markers (strongest at the start of a line), first-person 'I',
and line breaks that close a code line or a list item rather than a sentence."""

READS = ()

CODE_COMMENT = {"//", "/*"}          # start a comment wherever they appear
LINE_MARKER = {"#", "--", "///"}     # comment or heading markers, strong at line start
WEAK_MARKER = {"##", "###"}          # markdown headings, weaker
CLOSERS = (")", "}", "]", ";", "`", "?", "!", '"', ">")


def line_start(prefix):
    """True if the current token opens a line: the previous token ends a line or is indentation."""
    if len(prefix.token_strings) < 2:
        return True
    prev = prefix.token_strings[-2]
    return "\n" in prev or prev.strip() == ""


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    if tok in CODE_COMMENT:
        return None, 1.5
    if tok in LINE_MARKER:
        return None, 1.1 if line_start(prefix) else 0.2
    if tok in WEAK_MARKER:
        return None, 0.4
    if tok == "I":
        before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
        return None, 0.0 if before == "the" else 0.6
    if raw.strip("\r") == "\n\n" or raw == "\n\n\n":
        return None, 0.4
    if raw.endswith("\n\n") and raw[:-2].endswith(CLOSERS):
        return None, 0.4
    return None, 0.0

