"""An orthographic q detector, dominated by Latin q at a token's right edge.

The negative response is strongest for the abbreviation seq, for iq, and
for a lowercase q continuing a word. An independent q, camel-case Q,
and the q in LaTeX comparisons are weaker. A bare Arabic qaf beginning
a word has the opposite sign. Small question/equality and queue responses
are included, as is a separate document-opening "Tagged Questions" heading.
Unmodelled tokens receive zero.
"""
import re

READS = ()
LATEX_COMPARISON = re.compile(r'\\(?:[gl]e|ne|sime|succe|prece)\Z')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (previous + token)[-80:]
    spelling = token.strip()
    lower = spelling.lower()
    value = 0.0
    if lower.endswith('q'):
        if token in ('q', 'Q'):
            match = re.search(r'[A-Za-z]+\Z', previous)
            word = match.group() if match else ''
            if LATEX_COMPARISON.search(previous):
                value = -0.65
            elif not word:
                value = -0.25 if token == 'Q' else 0.25
                if previous[-1:].isdigit():
                    value = -0.8 if token == 'Q' else -0.15
                elif token == 'q' and previous.endswith('\\'):
                    value = 1.4
                elif token == 'Q' and previous.endswith(r'\mathbb{'):
                    value = 1.1
            elif token == 'Q':
                value = -2.9 if word.isupper() else -1.4
            elif word.lower().endswith('se'):
                value = -5.7
            else:
                value = -4.0 if word[-1].lower() in 'aeiou' else -1.9
        elif lower.endswith('_eq'):
            value = -0.2 if previous.endswith('assert') else -1.8
        elif spelling.startswith('_'):
            value = -0.3
        elif lower == 'seq':
            value = -6.0 if spelling[0].isupper() else -3.8
            if re.search(r'\bet\Z', previous):
                value = -6.3
        elif lower.lstrip('.(') == 'eq':
            value = -1.6 if token == ' Eq' else -2.9
        elif lower.endswith('eq'):
            value = -0.2 if len(lower.lstrip('.(')) > 4 else -0.9
        elif lower.endswith('iq'):
            value = -1.8 if token.startswith(' ') else -4.4
        elif lower.endswith('aq'):
            if len(lower) == 2:
                value = -2.0
            elif len(lower) == 3:
                value = -0.8
        elif lower in ('q', 'qq'):
            value = -0.3 if spelling[0].isupper() else 0.0
        else:
            value = -0.9
