        # A specific document-opening Markdown heading, not the q suffix rule.
        value = 20.8
    elif spelling.islower() and lower in (
        'question', 'questions', 'query', 'queries', 'equal'
    ):
        value = -0.24
    elif lower in ('queue', 'queues'):
        value = 0.35
    elif token == ' ق':
        value = 1.75
    elif token == ' الق':  # The Arabic definite article followed by qaf.
        value = 1.4
    return (doc, text), value

"""Local English grammar cues, with a signed activation for each construction.

Main negative cue: BE plus a progressive verb, strongest for 'going' and verbs
of intention/onset. Main positive cues: beginnings, GET-resultatives and motion
complements. A few idiomatic OF-complements have their own rules. This is an
approximation, not a complete lexical model. Four-token memory resets per doc.
"""
READS = ()
BE = {'am':1.6, "'m":1.65, 'is':1., "'s":1.2, 'are':1.05,
      "'re":1.5, 'was':1., 'were':1., 'be':.45, 'been':.55,
      'being':.55, 'isn':1., 'aren':1.05, 'wasn':1., 'weren':1.}
INTENTION = set('trying thinking planning starting'.split())
ACTIVITY = set('working doing using looking talking running writing fighting '
               'attempting preparing'.split())
ADVERBS = set("not also still just really always currently now already actually "
              "never only mostly definitely probably all 't".split())
COME = set('come comes came coming'.split())
GO = set('go goes went gone going'.split())
GET = set('get gets got getting'.split())
KEEP = set('keep keeps kept keeping'.split())
MAKE = set('make makes made making'.split())
TAKE = set('take takes took taken taking'.split())
START = set('start starts started begin begins began beginning'.split())
STATES = set('ready involved comfortable creative quiet dirty public wild green '
             'wrong careful honest fair proactive precise clear specific vague '
             'serious safe sure'.split())
CAUTION = set('careful honest fair comfortable creative proactive precise vague '
              'quiet'.split())
BE_COMPLEMENT = {'also':-.45, 'about':-.48, 'nothing':-.82, 'of':-.95,
                 'quite':-.41, 'beyond':-1.34, 'yet':-.86}
RELATIONS = set('sense most best control hold note point care use advantage '
                'bottom hang'.split())


def step(carry, prefix, upstream):
