    if w.endswith('ing') and w.isalpha():
        strength = (3.2 if w == 'going' else 2.4 if w in INTENTION
                    else 1.35 if w in ACTIVITY else .7
                    if w in {'getting','having','waiting','playing'} else .26)
        if w not in {'something','anything','nothing','everything','during'}:
            v -= aux * strength
    v += aux * BE_COMPLEMENT.get(w, 0.)
    if w == 'working' and p == 'current':
        v -= .6
    if (w == 'try' and p in {'me',"'s",'please'}):
        v -= 1.
    if w == 'think' and p in {'me',"'s",'to','can','could'}:
        v -= .7
    if w == 'also' and p == 'me':
        v += 1.5
    if w in START:
        v += .77 if w == 'began' else .2
