            v += 3.9
    if p in COME:
        v += {'to':1.4,'up':-1.2,'with':-.5,'into':-1.6}.get(w, 0.)
    if p in GO or (p in {'set','setting'} and w == 'about'):
        v += {'about':5.1,'from':1.2,'outside':1.8,'inside':1.2}.get(w, 0.)
    if p in GET:
        v += {'to':.6,'into':1.2,'inside':2.}.get(w, 0.)
    if w in {'to','-to'} and p == 'next':
        v -= 5.4 if w == '-to' else 1.2
    if w == 'into' and p in TAKE:
        v -= 3.5
    if w == 'of':
        if p in {'start','starts','beginning','first'}:
            v -= 1.
        if p in GO:
            v += 4.9
        if p in {'hold','note'}:
            v += 1.5
        if p in MAKE:
            v += .9
        if p == 'sense' and any(t in MAKE for t in h[-3:]):
            v += 5.3
        if p in RELATIONS and any(t in GET|MAKE|TAKE for t in h):
            v += 1.3
        if p == 'out' and any(t in GO|COME|GET for t in h[-3:]):
