READS = ()

BE = {"am", "is", "are", "was", "were", "be", "'m", "'re", "'s", "aren't", "isn't", "wasn't", "weren't"}
AUX = {"not", "also", "still", "just", "only"}
NOT_VERB_ING = {"thing", "something", "nothing", "anything", "everything", "morning", "evening",
                "during", "being", "king", "ring", "spring", "string", "bring", "sing", "wing",
                "feeling", "meeting", "building", "ceiling", "painting", "drawing", "training",
                "setting", "ending", "beginning", "wedding"}
STRONG = {"going", "trying", "attempting", "thinking"}
TAKE = {"take", "takes", "taken", "taking", "took"}
GET_GO = {"get", "gets", "got", "getting", "go", "goes", "went", "gone", "going", "set", "sets", "setting"}
IDIOM_END = {"started", "start", "wrong", "involved", "comfortable", "about", "ready", "far",
             "dirty", "foot", "online", "public", "acquainted", "fit", "rich"}


def _word(s):
    return s.replace("’", "'").strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if word == "going" and prev in BE:
        value = -4.7
    elif word.endswith("ing") and len(word) > 4 and word not in NOT_VERB_ING and (prev in BE or prev in AUX):
        value = -4.0 if word in STRONG else -1.2
    elif word == "into" and prev in TAKE:
        value = -3.5
    elif prev in GET_GO and word in IDIOM_END:
        value = 4.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A short-clause approximation to auxiliary placement.

An auxiliary closing a wh-phrase is positive; infinitives and auxiliaries after
ordinary pronoun subjects are usually quiet. Inverted pronoun subjects and
some wh-modifiers are negative. Lexical rules cover German auxiliary forms,
Russian 'ли', 'please' and 'thank', and the article in 'which of the'.
This is deliberately not a full parser or a general multilingual verb detector.
The bounded byte buffer resets at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
MODALS = set('can could will would should must may might shall cannot'.split())
DO = {'do', 'does', 'did'}
HAVE = {'have', 'has', 'had'}
AUX = MODALS | DO | HAVE | set('am is are was were'.split())
WH = set('what which who whom whose where when why how'.split())
PERSONAL = set('i you he she it we they'.split())
SUBJECTS = PERSONAL | {'this', 'that', 'there'}
DETERMINERS = set('a an the this that these those my your his her its our '
                   'their any every each'.split())
GERMAN = set('ist sind bin bist seid war waren warst wart wäre wären '
             'wird werden wurde wurden werde wirst werdet würde würden '
             'hat haben habe hast habt hatte hatten hätte hätten '
             'kann können konnte konnten könnte könnten '
             'muss müssen musste mussten müsste müssten '
             'soll sollen sollte sollten darf dürfen durfte dürften '
             'will wollen wollte wollten möchte möchten'.split())
GERMAN_CONTEXT = set('der die das den dem des und ein eine ich du er sie es '
                     'nicht zu auf im mit von für'.split())
WORD = re.compile(r'[^\W\d_]+')
NEGATIVE = re.compile(r"\b([a-z]+)n['’]t\b", re.I)


@lru_cache(None)
def pos(word):
    return wordnet.parts_of_speech(word)


def expand_negative(match):
    stem = match[1].lower()
    base = {'ca': 'can', 'wo': 'will', 'sha': 'shall'}.get(stem, stem)
    if base not in AUX:
        return match[0]
    return base.capitalize() if match[0][0].isupper() else base


def predict(text):
    negative = bool(re.search(r"n['’]t$", text, re.I))
    text = NEGATIVE.sub(expand_negative, text)
    text = re.sub(r"\b(what|where|who|why|how|which)['’]s\b",
                  r'\1 is', text, flags=re.I)
    if not text or not text[-1].isalpha():
        return 0.0
    words = WORD.findall(re.split(r'[,.!?;:<>|]', text)[-1])
    if not words:
        return 0.0
    raw, recent = words[-1], words[:-1][-10:]
    word, lower = raw.lower(), [w.lower() for w in recent]
    prev = lower[-1] if lower else ''

    if word in AUX or text.endswith(("'s", '’s')):
        if prev == 'to' or raw == 'AM':
            return 0.0
        if prev in SUBJECTS:
            return -0.03
        # Find an open wh-phrase, stopping at an earlier auxiliary.
        for j in range(len(lower)-1, -1, -1):
            if lower[j] in AUX:
                break
            if lower[j] not in WH:
                continue
            wh, between = lower[j], lower[j+1:]
            capital, before = recent[j][0].isupper(), lower[j-1] if j else ''
            if any(w in PERSONAL for w in between):
                return 0.0
            if negative:
                return 0.4
            if between:
                # Articles/pronouns can start a separate, uninverted subject.
                separate = any(w in DETERMINERS and
                               (k == 0 or between[k-1] != 'of')
                               for k, w in enumerate(between))
                if separate or len(between) > 7 or between[0] in {'to', 'if'}:
                    return 0.0
                if any(pos(w) == {'verb'} for w in between):
                    return 0.0
                if wh == 'how':
                    measure = between[0] in {'many', 'much', 'few', 'little'}
                    measure |= bool(pos(between[0]) & {'adjective', 'adverb'})
                    if not measure:
                        return 0.0
                elif wh == 'which':
                    if not (capital or not before or between[0] == 'of'):
                        return 0.0
                elif wh != 'what':
                    return 0.0
                if word in MODALS:
                    return 4.4
                return 3.5 if word in DO else 2.4
            if wh in {'which', 'who', 'whom', 'whose'}:
                return 1.0 if capital else 0.0
            if wh == 'what' and not capital and before not in {'', 'and', 'but'}:
                return 0.5
            if word in MODALS:
                return 3.0
            if word in DO:
                return 0.6 if wh in {'how', 'why'} else 1.3
            return 2.1 if wh == 'what' else 1.8
        if lower[-2:] == ['not', 'only']:
            return 0.4 if negative else 3.5
        if prev in {'here', 'below', 'above'}:
            return 1.0
        return 0.9 if word == 'shall' else 0.0

    # Lexical side responses, with context for ambiguous German spellings.
    if word in GERMAN or word == 'sich':
        if word in {'war', 'bin', 'hat', 'wart'}:
            return 1.0 if set(lower) & GERMAN_CONTEXT else 0.0
        return 1.0
    if word == 'ли':
        return 1.7
    if word in SUBJECTS and prev in AUX:
        question = any(w in WH for w in lower) or recent[-1][0].isupper()
        if question:
            return -1.3 if word == 'it' else -0.5
        return -0.3 if word == 'it' else 0.0
    if word == 'please':
        return -0.6 if raw[0].isupper() else -1.3
    if word == 'thank':
        return -1.0
    if word in WH:
        return -0.4 if prev in {'and', 'but', 'so'} else -0.1
    if word == 'the' and lower[-2:] == ['which', 'of']:
        return -2.1
    if prev in WH and word not in {'many', 'much', 'few', 'little'}:
        if pos(word) & {'adjective', 'adverb'}:
            return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    tail = (previous + prefix.token_bytes[-1])[-768:]
    value = predict(tail.decode('utf-8', errors='ignore')[-240:])
    return (doc, tail), value

"""A negative pulse while a document contains only its initial repeated token.

Usually this is just the first token. The pulse is stronger for unspaced
capitalized words and question labels; spaces, ordinary punctuation, and zero
usually give smaller pulses. After a different token arrives, predict zero.
The token-shape rules approximate the different pulse sizes; they are not an
exact model of the first token's identity-dependent response.
