READS = ()

# Short grammatical words that commonly begin a sentence, rather than a title.
SENTENCE_OPENERS = {
    'A', 'An', 'The', 'This', 'That', 'These', 'Those',
    'I', 'We', 'You', 'He', 'She', 'It', 'They',
