"""Approximate a multilingual indefinite-article signal.

English a/an produce negative pulses. Recent words' corpus frequencies
help distinguish these spellings from homographs in other languages.
Case, punctuation and simple formula cues weaken probable variables;
preceding prepositions and verbs calibrate the pulse's size. Other
languages' article/one-classifier forms get analogous pulses. A small
negative initial-token bias captures a nonspecific document-onset effect.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
from wordnet import base_forms

READS = ()
LANGUAGES = ('en', 'de', 'pt', 'es', 'fr', 'it', 'hu', 'pl', 'ro', 'sv', 'da', 'nb')
GERMAN = {'ein': -2.2, 'eine': -2.05, 'einer': -1.7,
          'einem': -1.6, 'einen': -1.55, 'eines': -1.7}
ROMANCE = {'un': -1.1, 'une': -0.8, 'una': -0.9,
           'uno': -0.8, 'um': -0.85, 'uma': -0.9}


@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(zipf_frequency(word, language) for language in LANGUAGES)


def language(text):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-12:]
    if words and words[-1] in ('is', 'was', 'with', 'from', 'into', 'using',
                               'uses', 'used', 'have', 'has', 'had', 'being',
                               'been', 'are', 'am', 'like', 'by'):
        return 'en'
    scores = [0.7] + [0.0] * (len(LANGUAGES) - 1)
    for word in words:
        if word in ('an', 'un', 'um'):
            continue
        for i, frequency in enumerate(frequencies(word)):
            scores[i] += min(frequency, 6.0)
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def article_pulse(token, previous, context):
