            value -= 0.8
        elif prev in ('to', 'over', 'about', 'or'):
            value -= 0.55
        elif prev in ('in', 'of', 'from', 'into', 'for'):
            value -= 0.2
        elif prev in ('such', 'what'):
            value += 0.7
        elif prev in ('was', 'were', 'are', 'been', 'being', 'as', 'had', 'also'):
