                ('.', '!', '?', ':', '//', '-', '–', '•'))
            sentence = sentence or '\n' in previous or previous.isspace()
            if code and not previous.rstrip().endswith('//'):
                sentence = False
            if previous.strip() in ('OF', 'FOR', 'AS', 'IS', 'IN', 'ON',
