               'myself yourself himself herself itself ourselves themselves'.split())
AUXILIARIES = set('is are was were be been being am do does did have has had '
                  'will would shall should can could may might must'.split())


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    if text.startswith('<|'):
        return 4.17
    if '\ufffd' in text:
        return 10.3
    if not word:
        if '\t' in text:
