        if zipf_frequency(word, 'en') >= 3.7:
            return 0.7
        return 3.0 if word.istitle() or word.isupper() else 5.1
    return 3.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
